import { CircleCheck, LoaderCircle, Mail } from "lucide-react";
import { type ReactNode, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export interface ForgotPasswordPageProps {
  onSubmit: (email: string) => Promise<void>;
  title?: string;
  description?: string;
  brand?: ReactNode;
  footer?: ReactNode;
}

/**
 * 忘记密码页：提交邮箱后进入「发送成功」终态（不暴露邮箱是否存在）。
 */
export function ForgotPasswordPage({
  onSubmit,
  title = "重置密码",
  description = "输入注册邮箱，我们会发送重置链接",
  brand,
  footer,
}: ForgotPasswordPageProps) {
  const [email, setEmail] = useState("");
  const [pending, setPending] = useState(false);
  const [sent, setSent] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    setError(null);
    setPending(true);
    try {
      await onSubmit(email);
      setSent(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : "发送失败，请重试");
    } finally {
      setPending(false);
    }
  }

  return (
    <main className="bg-background flex min-h-svh items-center justify-center p-6">
      <Card className="w-full max-w-sm">
        <CardHeader className="items-center text-center">
          {brand}
          <CardTitle className="text-[22px] font-semibold tracking-tight">{title}</CardTitle>
          {description ? <CardDescription>{description}</CardDescription> : null}
        </CardHeader>
        <CardContent>
          {sent ? (
            <div className="flex flex-col items-center gap-3 py-4 text-center">
              <span className="bg-status-info-bg text-status-info flex size-10 items-center justify-center rounded-full">
                <Mail className="size-5" />
              </span>
              <CircleCheck className="text-status-success size-5" />
              <p className="text-sm text-muted-foreground">
                如果该邮箱已注册，重置链接已发送至 <span className="text-foreground">{email}</span>
                。
              </p>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="flex flex-col gap-4">
              <div className="grid gap-2">
                <Label htmlFor="forgot-email">邮箱</Label>
                <Input
                  id="forgot-email"
                  type="email"
                  autoComplete="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </div>
              {error ? (
                <p role="alert" className="text-destructive text-sm">
                  {error}
                </p>
              ) : null}
              <Button type="submit" disabled={pending} className="w-full">
                {pending ? (
                  <LoaderCircle className="animate-spin" data-icon="inline-start" />
                ) : null}
                {pending ? "发送中…" : "发送重置链接"}
              </Button>
            </form>
          )}
        </CardContent>
        {footer ? <CardFooter className="justify-center text-sm">{footer}</CardFooter> : null}
      </Card>
    </main>
  );
}

/**
 * onboarding —— 带逻辑的首登引导向导（docs/blocks.md team/settings SaaS 模板）。
 *
 * 四步（Stepper 驱动，步骤间数据保留在向导 state）：欢迎 → 创建首个资源 → 邀请成员 →
 * 完成确认（summary）→ onComplete（宿主做完成跳转）。每步经 validate 前置校验；
 * 创建/邀请为异步动作（pending 透传 Stepper）。
 */
import { cn } from "cn";
import { PartyPopper, Plus, Trash2 } from "lucide-react";
import { useState } from "react";
import { z } from "zod";
import { Stepper } from "@/components/blocks/form/stepper/stepper";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

export interface OnboardingResourceInput {
  name: string;
  env: string;
}

export interface OnboardingInvite {
  email: string;
  role: string;
}

export interface OnboardingPayload {
  teamName: string;
  firstResource: OnboardingResourceInput | null;
  invites: OnboardingInvite[];
}

export interface OnboardingProps {
  /** 创建首个资源（第 2 步提交；返回错误信息则停留在本步） */
  onCreateResource?(input: OnboardingResourceInput): Promise<string | undefined | undefined>;
  /** 发送邀请（第 3 步“下一步”时提交已填行；可留到完成时统一处理） */
  onInviteMembers?(invites: OnboardingInvite[]): Promise<string | undefined | undefined>;
  /** 完成（summary 确认后；宿主做跳转） */
  onComplete(payload: OnboardingPayload): void | Promise<void>;
  /** 资源环境选项（默认 dev/staging/prod） */
  envOptions?: { value: string; label: string }[];
  /** 角色选项（默认 admin/member/viewer） */
  roleOptions?: { value: string; label: string }[];
  /** 团队名（欢迎步预填） */
  defaultTeamName?: string;
  className?: string;
}

const DEFAULT_ENV_OPTIONS = [
  { value: "dev", label: "开发" },
  { value: "staging", label: "预发" },
  { value: "prod", label: "生产" },
];
const DEFAULT_ROLE_OPTIONS = [
  { value: "admin", label: "Admin" },
  { value: "member", label: "Member" },
  { value: "viewer", label: "Viewer" },
];

export function Onboarding({
  onCreateResource,
  onInviteMembers,
  onComplete,
  envOptions = DEFAULT_ENV_OPTIONS,
  roleOptions = DEFAULT_ROLE_OPTIONS,
  defaultTeamName = "",
  className,
}: OnboardingProps) {
  // 步骤间数据保留（向导级 state；Stepper 只渲染当前步 content）
  const [teamName, setTeamName] = useState(defaultTeamName);
  const [resource, setResource] = useState<OnboardingResourceInput>({
    name: "",
    env: envOptions[0]?.value ?? "dev",
  });
  const [resourceCreated, setResourceCreated] = useState(false);
  const [invites, setInvites] = useState<OnboardingInvite[]>([
    { email: "", role: roleOptions[1]?.value ?? "member" },
  ]);

  const validEmail = (email: string): boolean => z.email().safeParse(email).success;

  async function createResource(): Promise<string | undefined> {
    if (onCreateResource === undefined) {
      setResourceCreated(true);
      return undefined;
    }
    const error = await onCreateResource(resource);
    if (error) return error;
    setResourceCreated(true);
    return undefined;
  }

  return (
    <div
      className={cn("bg-card mx-auto w-full max-w-2xl rounded-xl border p-6 sm:p-8", className)}
      data-slot="onboarding"
    >
      <div className="mb-6 flex items-center gap-2">
        <span className="bg-primary/10 text-primary ring-primary/15 flex size-8 items-center justify-center rounded-lg ring-1 ring-inset">
          <PartyPopper className="size-4" />
        </span>
        <div>
          <h1 className="text-lg font-semibold tracking-tight">欢迎加入</h1>
          <p className="text-muted-foreground text-[13px]">
            三步完成初始化：命名 → 建资源 → 邀人。
          </p>
        </div>
      </div>

      <Stepper
        nextLabel="下一步"
        doneLabel="完成初始化"
        steps={[
          {
            title: "欢迎",
            description: "给你的团队起个名字（之后可随时在设置中修改）。",
            content: (
              <div className="grid gap-2">
                <Label htmlFor="onboarding-team">团队名称</Label>
                <Input
                  id="onboarding-team"
                  value={teamName}
                  onChange={(e) => setTeamName(e.target.value)}
                  placeholder="如：Acme Platform"
                />
              </div>
            ),
            validate: () => (teamName.trim().length < 2 ? ["团队名称至少 2 个字符"] : []),
          },
          {
            title: "创建首个资源",
            description: "一个服务 / 项目即可开始（之后可创建更多）。",
            content: (
              <div className="grid gap-4">
                <div className="grid gap-2">
                  <Label htmlFor="onboarding-resource">资源名称</Label>
                  <Input
                    id="onboarding-resource"
                    value={resource.name}
                    onChange={(e) => setResource({ ...resource, name: e.target.value })}
                    placeholder="如：gateway"
                  />
                </div>
                <div className="grid gap-2">
                  <Label>环境</Label>
                  <Select
                    value={resource.env}
                    onValueChange={(v) => v !== null && setResource({ ...resource, env: v })}
                  >
                    <SelectTrigger className="w-40">
                      <SelectValue>
                        {envOptions.find((o) => o.value === resource.env)?.label ?? resource.env}
                      </SelectValue>
                    </SelectTrigger>
                    <SelectContent>
                      {envOptions.map((option) => (
                        <SelectItem key={option.value} value={option.value}>
                          {option.label}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                </div>
                {resourceCreated ? (
                  <p className="text-status-success text-[13px]">
                    已创建 {resource.name}（{resource.env}）—— 可直接进入下一步。
                  </p>
                ) : null}
              </div>
            ),
            validate: async () => {
              if (resource.name.trim().length < 2) return ["资源名称至少 2 个字符"];
              if (!resourceCreated) {
                const error = await createResource();
                return error ? [error] : [];
              }
              return [];
            },
          },
          {
            title: "邀请成员",
            description: "输入队友邮箱（可跳过，稍后在 Team 页邀请）。",
            content: (
              <div className="flex flex-col gap-2">
                {invites.map((invite, i) => (
                  <div key={i} className="flex items-center gap-2">
                    <Input
                      value={invite.email}
                      placeholder="teammate@example.com"
                      aria-label={`邀请邮箱 ${i + 1}`}
                      onChange={(e) => {
                        const next = [...invites];
                        const row = next[i];
                        if (row) next[i] = { ...row, email: e.target.value };
                        setInvites(next);
                      }}
                    />
                    <Select
                      value={invite.role}
                      onValueChange={(v) => {
                        if (v === null) return;
                        const next = [...invites];
                        const row = next[i];
                        if (row) next[i] = { ...row, role: v };
                        setInvites(next);
                      }}
                    >
                      <SelectTrigger className="w-32" aria-label={`角色 ${i + 1}`}>
                        <SelectValue>
                          {roleOptions.find((o) => o.value === invite.role)?.label ?? invite.role}
                        </SelectValue>
                      </SelectTrigger>
                      <SelectContent>
                        {roleOptions.map((option) => (
                          <SelectItem key={option.value} value={option.value}>
                            {option.label}
                          </SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                    <Button
                      type="button"
                      variant="ghost"
                      size="icon"
                      aria-label="移除该邀请"
                      disabled={invites.length === 1}
                      onClick={() => setInvites(invites.filter((_, k) => k !== i))}
                    >
                      <Trash2 />
                    </Button>
                  </div>
                ))}
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  className="self-start"
                  onClick={() =>
                    setInvites([...invites, { email: "", role: roleOptions[1]?.value ?? "member" }])
                  }
                >
                  <Plus data-icon="inline-start" />
                  再加一位
                </Button>
              </div>
            ),
            validate: async () => {
              const filled = invites.filter((invite) => invite.email.trim() !== "");
              const invalid = filled.filter((invite) => !validEmail(invite.email));
              if (invalid.length > 0) {
                return [`${invalid.length} 个邮箱格式无效`];
              }
              setInvites(filled);
              if (filled.length > 0 && onInviteMembers) {
                const error = await onInviteMembers(filled);
                if (error) return [error];
              }
              return [];
            },
          },
          {
            title: "完成",
            description: "确认初始化内容。",
            content: (
              <dl className="grid gap-2.5 rounded-lg border p-4 text-sm">
                <div className="flex justify-between gap-4">
                  <dt className="text-muted-foreground">团队</dt>
                  <dd className="font-medium">{teamName}</dd>
                </div>
                <div className="flex justify-between gap-4">
                  <dt className="text-muted-foreground">首个资源</dt>
                  <dd className="font-mono text-xs">
                    {resourceCreated || resource.name
                      ? `${resource.name} · ${resource.env}`
                      : "跳过"}
                  </dd>
                </div>
                <div className="flex justify-between gap-4">
                  <dt className="text-muted-foreground">邀请</dt>
                  <dd>
                    {invites.length === 0
                      ? "跳过"
                      : invites.map((invite) => invite.email).join("、")}
                  </dd>
                </div>
              </dl>
            ),
          },
        ]}
        onComplete={async () => {
          await onComplete({
            teamName,
            firstResource: resourceCreated ? resource : null,
            invites,
          });
        }}
      />
    </div>
  );
}

import { cn } from "cn";
import { LoaderCircle } from "lucide-react";
import { type ReactNode, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";

export interface OtpPageProps {
  /** 校验码长度（分格数），默认 6 */
  length?: number;
  /** 全部填满时自动提交；也可点击按钮提交 */
  onSubmit: (code: string) => Promise<void>;
  title?: string;
  description?: string;
  brand?: ReactNode;
  footer?: ReactNode;
}

/**
 * 验证码 / MFA 页：N 位分格输入（自动进格、退格回跳、粘贴整段填充、填满自动提交）。
 */
export function OtpPage({
  length = 6,
  onSubmit,
  title = "输入验证码",
  description = "验证码已发送至你的邮箱或手机",
  brand,
  footer,
}: OtpPageProps) {
  const [digits, setDigits] = useState<string[]>(() => Array.from({ length }, () => ""));
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const inputsRef = useRef<Array<HTMLInputElement | null>>([]);

  const code = digits.join("");

  async function submit(value: string) {
    setError(null);
    setPending(true);
    try {
      await onSubmit(value);
    } catch (err) {
      setError(err instanceof Error ? err.message : "验证失败，请重试");
      setDigits(Array.from({ length }, () => ""));
      inputsRef.current[0]?.focus();
    } finally {
      setPending(false);
    }
  }

  function setDigit(index: number, raw: string) {
    const value = raw.replace(/\D/g, "");
    if (value === "") {
      return;
    }
    setDigits((prev) => {
      const next = [...prev];
      // 支持一次输入/粘贴多位：从当前格起依次填充
      for (let offset = 0; offset < value.length && index + offset < length; offset++) {
        next[index + offset] = value[offset] ?? "";
      }
      const filled = next.join("");
      if (filled.length === length && !next.includes("")) {
        queueMicrotask(() => {
          const target = inputsRef.current[Math.min(index + value.length, length - 1)];
          target?.blur();
          void submit(filled);
        });
      }
      return next;
    });
    const focusIndex = Math.min(index + value.length, length - 1);
    inputsRef.current[focusIndex]?.focus();
  }

  function handleKeyDown(index: number, event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === "Backspace") {
      event.preventDefault();
      setDigits((prev) => {
        const next = [...prev];
        if (next[index]) {
          next[index] = "";
        } else if (index > 0) {
          next[index - 1] = "";
          inputsRef.current[index - 1]?.focus();
        }
        return next;
      });
    }
    if (event.key === "ArrowLeft" && index > 0) {
      inputsRef.current[index - 1]?.focus();
    }
    if (event.key === "ArrowRight" && index < length - 1) {
      inputsRef.current[index + 1]?.focus();
    }
  }

  return (
    <main className="bg-background flex min-h-svh items-center justify-center p-6">
      <Card className="w-full max-w-sm">
        <CardHeader className="items-center text-center">
          {brand}
          <CardTitle className="text-[22px] font-semibold tracking-tight">{title}</CardTitle>
          {description ? <CardDescription>{description}</CardDescription> : null}
        </CardHeader>
        <CardContent>
          <form
            onSubmit={(e) => {
              e.preventDefault();
              if (code.length === length && !code.includes("")) {
                void submit(code);
              }
            }}
            className="flex flex-col items-center gap-4"
          >
            <fieldset className="flex gap-2" aria-label={`${length} 位验证码`}>
              {digits.map((digit, index) => (
                <Input
                  key={index}
                  ref={(el) => {
                    inputsRef.current[index] = el;
                  }}
                  inputMode="numeric"
                  autoComplete={index === 0 ? "one-time-code" : "off"}
                  maxLength={length}
                  value={digit}
                  autoFocus={index === 0}
                  disabled={pending}
                  className={cn(
                    "size-11 text-center text-base font-medium tabular-nums",
                    error && "aria-invalid:border-destructive",
                  )}
                  onChange={(e) => setDigit(index, e.target.value)}
                  onKeyDown={(e) => handleKeyDown(index, e)}
                />
              ))}
            </fieldset>
            {error ? (
              <p role="alert" className="text-destructive text-sm">
                {error}
              </p>
            ) : null}
            <Button type="submit" className="w-full" disabled={pending || code.includes("")}>
              {pending ? <LoaderCircle className="animate-spin" data-icon="inline-start" /> : null}
              {pending ? "验证中…" : "验证"}
            </Button>
          </form>
        </CardContent>
        {footer ? <CardFooter className="justify-center text-sm">{footer}</CardFooter> : null}
      </Card>
    </main>
  );
}

import { LoaderCircle } from "lucide-react";
import { type ReactNode, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export interface SignInPageProps {
  onSubmit: (credentials: { email: string; password: string }) => Promise<void>;
  title?: string;
  description?: string;
  /** 品牌位（logo + 产品名），渲染在表单上方 */
  brand?: ReactNode;
  /** 表单下方区域（注册 / 忘记密码链接等） */
  footer?: ReactNode;
  submitLabel?: string;
}

/**
 * 登录页：品牌位 + 邮箱密码表单 + 错误展示。
 * onSubmit 抛错 → 表单内联展示（如 HttpError(401) 的「邮箱或密码错误」）；next 回跳由宿主处理。
 */
export function SignInPage({
  onSubmit,
  title = "欢迎回来",
  description = "登录你的账号以继续",
  brand,
  footer,
  submitLabel = "登录",
}: SignInPageProps) {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    setError(null);
    setPending(true);
    try {
      await onSubmit({ email, password });
    } catch (err) {
      setError(err instanceof Error ? err.message : "登录失败，请重试");
    } finally {
      setPending(false);
    }
  }

  return (
    <main className="bg-background flex min-h-svh items-center justify-center p-6">
      <Card className="w-full max-w-sm">
        <CardHeader className="items-center text-center">
          {brand}
          <CardTitle className="text-[22px] font-semibold tracking-tight">{title}</CardTitle>
          {description ? <CardDescription>{description}</CardDescription> : null}
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="flex flex-col gap-4">
            <div className="grid gap-2">
              <Label htmlFor="signin-email">邮箱</Label>
              <Input
                id="signin-email"
                type="email"
                autoComplete="email"
                required
                placeholder="you@example.com"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="signin-password">密码</Label>
              <Input
                id="signin-password"
                type="password"
                autoComplete="current-password"
                required
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
            </div>
            {error ? (
              <p role="alert" className="text-destructive text-sm">
                {error}
              </p>
            ) : null}
            <Button type="submit" disabled={pending} className="w-full">
              {pending ? <LoaderCircle className="animate-spin" data-icon="inline-start" /> : null}
              {pending ? "登录中…" : submitLabel}
            </Button>
          </form>
        </CardContent>
        {footer ? <CardFooter className="justify-center text-sm">{footer}</CardFooter> : null}
      </Card>
    </main>
  );
}

import { CircleCheck, LoaderCircle } from "lucide-react";
import { type ReactNode, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";

export interface SignUpPageProps {
  onSubmit: (values: { name: string; email: string; password: string }) => Promise<void>;
  title?: string;
  description?: string;
  brand?: ReactNode;
  footer?: ReactNode;
}

/**
 * 注册页：姓名 + 邮箱 + 密码 + 确认密码（客户端一致性校验）。
 * 提交成功后由宿主切换 success 视图或直接登录。
 */
export function SignUpPage({
  onSubmit,
  title = "创建账号",
  description = "几秒钟完成注册",
  brand,
  footer,
}: SignUpPageProps) {
  const [name, setName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);
  const [done, setDone] = useState(false);

  async function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    setError(null);
    if (password !== confirm) {
      setError("两次输入的密码不一致");
      return;
    }
    setPending(true);
    try {
      await onSubmit({ name, email, password });
      setDone(true);
    } catch (err) {
      setError(err instanceof Error ? err.message : "注册失败，请重试");
    } finally {
      setPending(false);
    }
  }

  return (
    <main className="bg-background flex min-h-svh items-center justify-center p-6">
      <Card className="w-full max-w-sm">
        <CardHeader className="items-center text-center">
          {brand}
          <CardTitle className="text-[22px] font-semibold tracking-tight">{title}</CardTitle>
          {description ? <CardDescription>{description}</CardDescription> : null}
        </CardHeader>
        <CardContent>
          {done ? (
            <div className="flex flex-col items-center gap-2 py-4 text-center">
              <CircleCheck className="text-status-success size-8" />
              <p className="text-sm text-muted-foreground">注册成功，请查收验证邮件完成激活。</p>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="flex flex-col gap-4">
              <div className="grid gap-2">
                <Label htmlFor="signup-name">姓名</Label>
                <Input
                  id="signup-name"
                  autoComplete="name"
                  required
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="signup-email">邮箱</Label>
                <Input
                  id="signup-email"
                  type="email"
                  autoComplete="email"
                  required
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="signup-password">密码</Label>
                <Input
                  id="signup-password"
                  type="password"
                  autoComplete="new-password"
                  required
                  minLength={8}
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />
              </div>
              <div className="grid gap-2">
                <Label htmlFor="signup-confirm">确认密码</Label>
                <Input
                  id="signup-confirm"
                  type="password"
                  autoComplete="new-password"
                  required
                  value={confirm}
                  onChange={(e) => setConfirm(e.target.value)}
                />
              </div>
              {error ? (
                <p role="alert" className="text-destructive text-sm">
                  {error}
                </p>
              ) : null}
              <Button type="submit" disabled={pending} className="w-full">
                {pending ? (
                  <LoaderCircle className="animate-spin" data-icon="inline-start" />
                ) : null}
                {pending ? "提交中…" : "创建账号"}
              </Button>
            </form>
          )}
        </CardContent>
        {footer ? <CardFooter className="justify-center text-sm">{footer}</CardFooter> : null}
      </Card>
    </main>
  );
}

