export interface CellIdProps {
  value: string | undefined;
  /** 显示位数（前缀截断展示，复制始终全量），默认 8 */
  chars?: number;
  className?: string;
}

/** ID 单元格：mono + 截断 + hover 复制（复制成功 2s 反馈） */
export function CellId({ value, chars = 8, className }: CellIdProps) {
  const [copied, setCopied] = useState(false);
  useEffect(() => {
    if (!copied) return;
    const timer = setTimeout(() => setCopied(false), 2000);
    return () => clearTimeout(timer);
  }, [copied]);

  if (value === undefined || value === null || value === "") {
    return <span className={cn("text-muted-foreground font-mono text-xs", className)}>—</span>;
  }

  const display = value.length > chars ? value.slice(0, chars) : value;
  return (
    <button
      type="button"
      title={`复制 ${value}`}
      onClick={() => {
        if (navigator?.clipboard) {
          void navigator.clipboard.writeText(value);
          setCopied(true);
        }
      }}
      className={cn(
        "group/cell-id inline-flex max-w-full items-center gap-1 rounded font-mono text-xs",
        "text-muted-foreground transition-colors hover:text-foreground",
        className,
      )}
      data-slot="cell-id"
    >
      <span className="truncate">{display}</span>
      {copied ? (
        <Check className="size-3 shrink-0 text-status-success" />
      ) : (
        <Copy className="size-3 shrink-0 opacity-0 transition-opacity group-hover/cell-id:opacity-100" />
      )}
    </button>
  );
}

import { cn } from "cn";

export type CellNumberFormat = "int" | "decimal" | "percent" | "bytes";

function formatValue(value: number, format: CellNumberFormat): string {
  switch (format) {
    case "int":
      return new Intl.NumberFormat(undefined, { maximumFractionDigits: 0 }).format(value);
    case "decimal":
      return new Intl.NumberFormat(undefined, {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2,
      }).format(value);
    case "percent":
      return new Intl.NumberFormat(undefined, {
        style: "percent",
        minimumFractionDigits: 0,
        maximumFractionDigits: 1,
      }).format(value);
    case "bytes": {
      const units = ["B", "KB", "MB", "GB", "TB"];
      let v = value;
      let unit = 0;
      while (v >= 1024 && unit < units.length - 1) {
        v /= 1024;
        unit += 1;
      }
      return `${new Intl.NumberFormat(undefined, { maximumFractionDigits: 1 }).format(v)} ${units[unit]}`;
    }
  }
}

export interface CellNumberProps {
  value: number | undefined | null;
  format?: CellNumberFormat;
  /** 单位后缀（如 " 个" / "ms"） */
  unit?: string;
  className?: string;
}

/** 数值单元格：tabular-nums + Intl 格式化（int/decimal/percent/bytes） + 可选单位 */
export function CellNumber({ value, format = "int", unit, className }: CellNumberProps) {
  if (value === undefined || value === null || Number.isNaN(value)) {
    return (
      <span className={cn("text-muted-foreground tabular-nums text-[13px]", className)}>—</span>
    );
  }
  return (
    <span className={cn("tabular-nums text-[13px]", className)} data-slot="cell-number">
      {formatValue(value, format)}
      {unit ? <span className="text-muted-foreground ml-0.5 text-xs">{unit}</span> : null}
    </span>
  );
}

import { cn } from "cn";
import type { StatusBadgeTone } from "@/components/blocks/shared/status-badge/status-badge";

export interface CellProgressProps {
  /** 0-100 百分比；或 {current,total} 自动换算 */
  value: number | { current: number; total: number } | undefined;
  /** 状态色（progress 前景色走 --status-* 令牌；缺省用 primary） */
  state?: StatusBadgeTone;
  /** 是否显示百分比数字（默认 true） */
  showValue?: boolean;
  className?: string;
}

const stateFill: Record<StatusBadgeTone, string> = {
  success: "[&::-webkit-progress-value]:bg-status-success [&::-moz-progress-bar]:bg-status-success",
  warning: "[&::-webkit-progress-value]:bg-status-warning [&::-moz-progress-bar]:bg-status-warning",
  danger: "[&::-webkit-progress-value]:bg-status-danger [&::-moz-progress-bar]:bg-status-danger",
  info: "[&::-webkit-progress-value]:bg-status-info [&::-moz-progress-bar]:bg-status-info",
  neutral:
    "[&::-webkit-progress-value]:bg-muted-foreground [&::-moz-progress-bar]:bg-muted-foreground",
};

/** 进度单元格：语义 <progress>（状态色映射 --status-*）+ 百分比；支持 {current,total} 形态 */
export function CellProgress({ value, state, showValue = true, className }: CellProgressProps) {
  let percent: number | undefined;
  if (typeof value === "number") {
    percent = value;
  } else if (value && typeof value === "object") {
    percent = value.total > 0 ? Math.round((value.current / value.total) * 100) : 0;
  }
  if (percent === undefined || Number.isNaN(percent)) {
    return <span className={cn("text-muted-foreground text-[13px]", className)}>—</span>;
  }
  const clamped = Math.max(0, Math.min(100, percent));
  return (
    <span className={cn("inline-flex items-center gap-2", className)} data-slot="cell-progress">
      <progress
        value={clamped}
        max={100}
        aria-label={`${clamped}%`}
        className={cn(
          "bg-muted h-1.5 w-24 overflow-hidden rounded-full",
          "[&::-webkit-progress-bar]:bg-transparent [&::-webkit-progress-value]:rounded-full [&::-moz-progress-bar]:rounded-full",
          "[&::-webkit-progress-value]:bg-primary [&::-moz-progress-bar]:bg-primary",
          state ? stateFill[state] : undefined,
        )}
      />
      {showValue ? (
        <span className="text-muted-foreground tabular-nums text-xs">{clamped}%</span>
      ) : null}
    </span>
  );
}

import { cn } from "cn";
