const DEFAULT_MAP: Record<string, StatusBadgeTone> = {
  running: "success",
  active: "success",
  succeeded: "success",
  healthy: "success",
  degraded: "warning",
  pending: "warning",
  queued: "warning",
  warning: "warning",
  failed: "danger",
  error: "danger",
  stopped: "neutral",
  cancelled: "neutral",
  draft: "neutral",
};

/** 状态单元格：StatusBadge 别名映射（未登记的值回落 neutral，不做硬编码色） */
