import {
  type DateTimePrefs,
  formatAbsolute,
  formatRelative,
  useDateTimePrefs,
  useNow,
} from "@patterns-ui/core/datetime";
import { cn } from "cn";
import { useEffect, useState } from "react";

const MODE_KEY = "fc:cell-time-mode";

type CellTimeMode = "relative" | "absolute";

function readMode(): CellTimeMode {
  try {
    const raw = globalThis.localStorage?.getItem(MODE_KEY);
    return raw === "absolute" ? "absolute" : "relative";
  } catch {
    return "relative";
  }
}

/** mode 的读取收敛（首次 render 用 relative，effect 内按偏好校正；SSR 安全） */
function useMode(): [CellTimeMode, (m: CellTimeMode) => void] {
  const [mode, setMode] = useState<CellTimeMode>("relative");
  useEffect(() => {
    setMode(readMode());
  }, []);
  return [mode, setMode];
}

export interface CellTimeProps {
  value: string | number | Date | undefined;
  className?: string;
}

/** 时间单元格：时区感知；点击切换 相对↔绝对（偏好记忆 localStorage 'fc:cell-time-mode'） */
export function CellTime({ value, className }: CellTimeProps) {
  const { prefs } = useDateTimePrefs();
  const now = useNow(30_000);
  const [mode, setMode] = useMode();

  const date =
    value === undefined || value === null || value === ""
      ? undefined
      : value instanceof Date
        ? value
        : new Date(value);
  if (date === undefined || Number.isNaN(date.getTime())) {
    return <span className={cn("text-muted-foreground text-[13px]", className)}>—</span>;
  }
  const iso = date.toISOString();
  const absolutePrefs: DateTimePrefs = {
    ...prefs,
    absolutePattern: prefs.absolutePattern ?? "datetime",
  };

  return (
    <button
      type="button"
      title={`切换显示（当前：${mode === "relative" ? "相对" : "绝对"}）
${formatAbsolute(iso, absolutePrefs)}`}
      onClick={() => {
        const next: CellTimeMode = mode === "relative" ? "absolute" : "relative";
        try {
          globalThis.localStorage?.setItem(MODE_KEY, next);
        } catch {
          /* 非浏览器环境 */
        }
        setMode(next);
      }}
      className={cn(
        "text-muted-foreground tabular-nums text-[13px] transition-colors hover:text-foreground",
        className,
      )}
      data-slot="cell-time"
    >
      {mode === "relative" ? formatRelative(iso, now) : formatAbsolute(iso, absolutePrefs)}
    </button>
  );
}

import { cn } from "cn";
import type { AvatarUser } from "@/components/blocks/shared/user-avatar/user-avatar";
import { UserAvatar } from "@/components/blocks/shared/user-avatar/user-avatar";

export interface CellUserProps {
  /** 单个用户或用户组（>2 个截断为 "+N"） */
  user?: AvatarUser | AvatarUser[];
  /** 无 user 对象时的兜底解析（如 owner id → 用户对象） */
  id?: string;
  resolve?: (id: string) => AvatarUser | undefined;
  size?: "sm" | "default" | "lg";
  className?: string;
}

/** 用户单元格：头像 + 名；数组时名逗号连接、超过 2 个截断 +N */
export function CellUser({ user, id, resolve, size = "sm", className }: CellUserProps) {
  const users: AvatarUser[] = Array.isArray(user) ? user : user ? [user] : [];
  const resolved =
    users.length === 0 && id && resolve
      ? [resolve(id)].filter((u): u is AvatarUser => u !== undefined)
      : users;

  if (resolved.length === 0) {
    return <span className={cn("text-muted-foreground text-[13px]", className)}>—</span>;
  }

  const visible = resolved.slice(0, 2);
  const overflow = resolved.length - visible.length;
  const label = visible.map((u) => u.name).join(", ") + (overflow > 0 ? ` +${overflow}` : "");

  return (
    <span className={cn("inline-flex items-center gap-2", className)} data-slot="cell-user">
      <span className="inline-flex -space-x-1.5">
        {visible.map((u, i) => (
          <UserAvatar
            key={`${u.name}-${i}`}
            user={u}
            size={size}
            className="ring-2 ring-background"
          />
        ))}
      </span>
      <span className="truncate text-[13px]" title={resolved.map((u) => u.name).join(", ")}>
        {label}
      </span>
    </span>
  );
}

import { cn } from "cn";
import { AlertTriangle, Loader2 } from "lucide-react";
import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";

export interface ConfirmDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: React.ReactNode;
  description?: React.ReactNode;
  /** 危险操作（红色确认按钮 + 警示图标） */
  danger?: boolean;
  /** 高危变体：需输入该名称/标识才允许确认 */
  typeToConfirm?: string;
  /** typeToConfirm 输入框提示（默认取 typeToConfirm 本身） */
  typeToConfirmLabel?: string;
  confirmLabel?: string;
  cancelLabel?: string;
  /** 确认中（禁用 + 转圈） */
  pending?: boolean;
  onConfirm: () => void | Promise<void>;
}

/**
 * 确认框：普通变体 + `typeToConfirm` 高危变体（输入指定名称才解锁确认按钮）。
 * danger 样式走 destructive 语义 token（--status-danger / --destructive）。
 */
export function ConfirmDialog({
  open,
  onOpenChange,
  title,
  description,
  danger = false,
  typeToConfirm,
  typeToConfirmLabel,
  confirmLabel = "确认",
  cancelLabel = "取消",
  pending = false,
  onConfirm,
}: ConfirmDialogProps) {
  const [typed, setTyped] = useState("");
  useEffect(() => {
    if (!open) setTyped("");
  }, [open]);

  const needsTyping = typeToConfirm !== undefined && typeToConfirm !== "";
  const canConfirm = !needsTyping || typed === typeToConfirm;

  return (
    <Dialog open={open} onOpenChange={(next) => (pending ? undefined : onOpenChange(next))}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle className={cn("flex items-center gap-2", danger && "text-destructive")}>
            {danger ? <AlertTriangle className="size-5 shrink-0" /> : null}
            {title}
          </DialogTitle>
          {description ? <DialogDescription>{description}</DialogDescription> : null}
        </DialogHeader>

        {needsTyping ? (
          <div className="space-y-1.5">
            <p className="text-muted-foreground text-sm">
              输入{" "}
              <span className="text-foreground font-medium">
                {typeToConfirmLabel ?? typeToConfirm}
              </span>{" "}
              以确认操作：
            </p>
            <Input
              value={typed}
              autoComplete="off"
              spellCheck={false}
              placeholder={typeToConfirmLabel ?? typeToConfirm}
              className="font-mono"
              onChange={(e) => setTyped(e.target.value)}
            />
          </div>
        ) : null}

        <DialogFooter>
          <Button variant="outline" disabled={pending} onClick={() => onOpenChange(false)}>
            {cancelLabel}
          </Button>
          <Button
            variant={danger ? "destructive" : "default"}
            disabled={!canConfirm || pending}
            onClick={() => {
              void onConfirm();
            }}
          >
            {pending ? <Loader2 className="animate-spin" /> : null}
            {confirmLabel}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

