import { cn } from "cn";
import { ArrowLeft, ArrowRight, Check, Loader2 } from "lucide-react";
import { type ReactNode, useState } from "react";
import { Button } from "@/components/ui/button";

export interface StepperStep {
  title: string;
  description?: string;
  /** 步骤内容（最后一步可放 summary） */
  content: ReactNode;
  /**
   * 「下一步 / 完成」前校验：返回错误文案数组（空数组/undefined = 通过）；
   * 可异步（返回 Promise）。
   */
  validate?: () => string[] | undefined | Promise<string[] | undefined>;
}

export interface StepperProps {
  steps: StepperStep[];
  /** 全部步骤通过后触发（完成） */
  onComplete: () => void | Promise<void>;
  /** 完成按钮 pending 态 */
  pending?: boolean;
  nextLabel?: string;
  doneLabel?: string;
  className?: string;
}

/**
 * 分步向导：步骤指示（done/current/waiting 三态）+ 每步「下一步」前校验 +
 * 错误提示 + 上一步回退 + 完成回调。summary 由最后一步的 content 提供。
 */
export function Stepper({
  steps,
  onComplete,
  pending = false,
  nextLabel = "下一步",
  doneLabel = "完成",
  className,
}: StepperProps) {
  const [index, setIndex] = useState(0);
  const [errors, setErrors] = useState<string[]>([]);
  const [validating, setValidating] = useState(false);
  const step = steps[index];
  const isLast = index === steps.length - 1;

  async function goNext(): Promise<void> {
    if (!step) return;
    setValidating(true);
    let problems: string[] | undefined;
    try {
      problems = await step.validate?.();
    } finally {
      setValidating(false);
    }
    if (problems && problems.length > 0) {
      setErrors(problems);
      return;
    }
    setErrors([]);
    if (isLast) {
      await onComplete();
      return;
    }
    setIndex((i) => Math.min(i + 1, steps.length - 1));
  }

  return (
    <div className={cn("flex flex-col gap-6", className)}>
      {/* 步骤指示器 */}
      <ol className="flex flex-wrap items-center gap-2">
        {steps.map((s, i) => {
          const state = i < index ? "done" : i === index ? "current" : "waiting";
          return (
            <li key={s.title} className="flex items-center gap-2">
              <span
                aria-current={state === "current" ? "step" : undefined}
                className={cn(
                  "flex size-6 items-center justify-center rounded-full border text-xs font-medium",
                  state === "done" &&
                    "border-status-success/40 bg-status-success-bg text-status-success",
                  state === "current" && "border-primary bg-primary text-primary-foreground",
                  state === "waiting" && "text-muted-foreground border-border",
                )}
              >
                {state === "done" ? <Check className="size-3.5" /> : i + 1}
              </span>
              <span
                className={cn(
                  "text-sm",
                  state === "current" ? "font-medium" : "text-muted-foreground",
                )}
              >
                {s.title}
              </span>
              {i < steps.length - 1 ? (
                <span aria-hidden="true" className="bg-border mx-1 h-px w-6 sm:w-10" />
              ) : null}
            </li>
          );
        })}
      </ol>

      {/* 当前步内容（含 summary） */}
      <div className="min-h-0 flex-1">
        {step ? (
          <div className="flex flex-col gap-4">
            {step.description ? (
              <p className="text-muted-foreground text-sm">{step.description}</p>
            ) : null}
            {step.content}
          </div>
        ) : null}
      </div>

      {/* 校验错误 */}
      {errors.length > 0 ? (
        <div role="alert" className="text-destructive space-y-1 text-sm">
          {errors.map((message) => (
            <p key={message}>· {message}</p>
          ))}
        </div>
      ) : null}

      {/* 导航 */}
      <div className="flex items-center justify-between">
        <Button
          type="button"
          variant="ghost"
          disabled={index === 0 || validating || pending}
          onClick={() => {
            setErrors([]);
            setIndex((i) => Math.max(0, i - 1));
          }}
        >
          <ArrowLeft /> 上一步
        </Button>
        <Button
          type="button"
          disabled={validating || pending}
          onClick={() => {
            void goNext();
          }}
        >
          {validating || pending ? <Loader2 className="animate-spin" /> : null}
          {isLast ? doneLabel : nextLabel}
          {isLast ? null : <ArrowRight />}
        </Button>
      </div>
    </div>
  );
}

/**
 * typed-form-field 共享上下文与字段外壳（docs/blocks.md form/typed-form-field）。
 *
 * TanStack Form v1（@tanstack/react-form ^1.33）组合 API：
 * - `createFormHookContexts()` → { fieldContext, useFieldContext, useFormContext, formContext }
 * - `createFormHook({ fieldContext, formContext, fieldComponents, formComponents })`
 * - 字段渲染：`<form.AppField name="x">{(field) => <field.TextWidget />}</form.AppField>`
 *   （children render prop；field API 上合并了 fieldComponents，v1.33 无 component prop）
 * - 服务端错误：onSubmit 内 `formApi.setErrorMap({ onSubmit: { fields, form } })`
 *   （onSubmit 返回值在 v1.33 被忽略）
 */
import { createFormHookContexts } from "@tanstack/react-form";
import { cn } from "cn";
import { type ReactNode, useId } from "react";
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldError,
  FieldLabel,
} from "@/components/ui/field";

export const { fieldContext, useFieldContext, useFormContext, formContext } =
  createFormHookContexts();

/** TanStack Form 错误值 → 文案（string | { message }） */
export function fieldMessage(error: unknown): string {
  if (error === undefined || error === null) return "";
  if (typeof error === "string") return error;
  if (typeof error === "object") {
    if ("message" in error) {
      const message = (error as { message?: unknown }).message;
      if (typeof message === "string" && message !== "") return message;
    }
    if ("issues" in error && Array.isArray((error as { issues: unknown[] }).issues)) {
      const issues = (error as { issues: { message?: string }[] }).issues
        .map((i) => i?.message)
        .filter(Boolean);
      if (issues.length > 0) return issues.join("；");
    }
    try {
      return JSON.stringify(error);
    } catch {
      return String(error);
    }
  }
  return String(error);
}

/**
 * 合并字段错误：meta.errors（聚合数组）优先；为空时回落 errorMap 各时相值
 * （服务端 setErrorMap 后 errors 数组可能尚未聚合，errorMap 永远在）。
 */
export function collectFieldErrors(meta: {
  errors: unknown[];
  errorMap: Record<string, unknown>;
}): string[] {
  const fromErrors = meta.errors.map(fieldMessage).filter(Boolean);
  if (fromErrors.length > 0) return fromErrors;
  return Object.values(meta.errorMap ?? {})
    .map(fieldMessage)
    .filter(Boolean);
}

export interface FieldShellProps {
  label?: ReactNode;
  description?: ReactNode;
  /** 错误文案列表（空 = 无错误显示） */
  errors?: string[];
  required?: boolean;
  /** 字段主体（受控输入） */
  children: ReactNode;
  /** 附加到 label 的 htmlFor */
  htmlFor?: string;
  className?: string;
  /** 行内布局（switch 等宽控件用） */
  inline?: boolean;
}

/** 统一字段布局：label / description / 控件 / error（required 加 *；错误态红色） */
export function FieldShell({
  label,
  description,
  errors,
  required,
  children,
  htmlFor,
  className,
  inline = false,
}: FieldShellProps) {
  const id = useId();
  return (
    <Field
      data-invalid={errors !== undefined && errors.length > 0 ? true : undefined}
      orientation={inline ? "horizontal" : "vertical"}
      className={cn("gap-2", className)}
    >
      {label ? (
        <FieldLabel htmlFor={htmlFor ?? id}>
          {label}
          {required ? (
            <span aria-hidden="true" className="text-destructive">
              *
            </span>
          ) : null}
        </FieldLabel>
      ) : null}
      <FieldContent>
        {children}
        {description ? <FieldDescription>{description}</FieldDescription> : null}
        <FieldError errors={errors?.map((message) => ({ message }))} />
      </FieldContent>
    </Field>
  );
}

/**
 * typed-form-field —— TanStack Form v1 组合工厂 + widget 注册（docs/blocks.md form/）。
 *
 * 用法（demo / 用户项目共用同一 contexts）：
 * ```tsx
 * const { useAppForm, withForm, SubmitButton, FormMessage } = createTypedForm()
 * const form = useAppForm({
 *   defaultValues,
 *   validators: { onChange: zodSchema },      // zod v4 Standard Schema 直传
 *   onSubmit: async ({ value, formApi }) => {
 *     const result = await resourceForm.onSubmit(value)   // core useResourceForm
 *     if (!result.ok) {
 *       formApi.setErrorMap({ onSubmit: { fields: result.fieldErrors, form: result.formError } })
 *     }
 *   },
 * })
 * <form onSubmit={(e) => { e.preventDefault(); void form.handleSubmit() }}>
 *   <form.AppForm>
 *     <form.AppField name="name">{(field) => <field.TextWidget label="名称" required />}</form.AppField>
 *   </form.AppForm>
 * </form>
 * ```
 */
import { createFormHook } from "@tanstack/react-form";
import { Loader2 } from "lucide-react";
import type { ComponentType, ReactNode } from "react";
import { Button } from "@/components/ui/button";
import {
  collectFieldErrors,
  fieldContext,
  fieldMessage,
  formContext,
  useFormContext,
} from "./contexts";
import {
  type DateRangeValue,
  DateRangeWidget,
  DateWidget,
  JsonWidget,
  type KvPair,
  KvPairsWidget,
  MultiSelectWidget,
  NumberWidget,
  RepeatableRowsWidget,
  SecretWidget,
  SelectWidget,
  SwitchWidget,
  TagsWidget,
  TextareaWidget,
  TextWidget,
  type UploadedFile,
  UploadWidget,
} from "./widgets";

/** 内建字段 widget 全家（注册进 fieldComponents → field.<Widget> 直接可用） */
export const typedFieldComponents = {
  TextWidget,
  TextareaWidget,
  NumberWidget,
  SelectWidget,
  MultiSelectWidget,
  TagsWidget,
  SwitchWidget,
  DateWidget,
  DateRangeWidget,
  SecretWidget,
  KvPairsWidget,
  UploadWidget,
  JsonWidget,
  RepeatableRowsWidget,
} as const;

// ---------------------------------------------------------------------------
// 表单级组件（formComponents → form.SubmitButton / form.FormMessage）
// ---------------------------------------------------------------------------

/** 提交按钮：订阅 canSubmit/isSubmitting（校验不过禁用；提交中转圈） */
export function SubmitButton({
  label = "保存",
  pendingLabel = "保存中…",
  disabled,
}: {
  label?: ReactNode;
  pendingLabel?: ReactNode;
  disabled?: boolean;
}) {
  const form = useFormContext();
  return (
    <form.Subscribe
      selector={(s: { canSubmit: boolean; isSubmitting: boolean }) =>
        [s.canSubmit, s.isSubmitting] as const
      }
    >
      {([canSubmit, isSubmitting]: readonly [boolean, boolean]) => (
        <Button type="submit" disabled={disabled || isSubmitting || !canSubmit}>
          {isSubmitting ? <Loader2 className="animate-spin" /> : null}
          {isSubmitting ? pendingLabel : label}
        </Button>
      )}
    </form.Subscribe>
  );
}

/** 表单级错误/提示位（onSubmit setErrorMap 的 form 段 + onServer 时相） */
export function FormMessage() {
  const form = useFormContext();
  return (
    <form.Subscribe selector={(s: { errorMap: Record<string, unknown> }) => s.errorMap}>
      {(errorMap: Record<string, unknown>) => {
        const messages = collectFieldErrors({ errors: [], errorMap });
        if (messages.length === 0) return null;
        return (
          <div role="alert" className="text-destructive text-sm">
            {messages.join("；")}
          </div>
        );
      }}
    </form.Subscribe>
  );
}

export const typedFormComponents = { SubmitButton, FormMessage } as const;

/**
 * 松组件形态：TanStack createFormHook 的 fieldComponents/formComponents 官方签名即
 * `Record<string, ComponentType<any>>`（widget 接收的 props 由各字段自带泛型决定）。
 */
// biome-ignore lint/suspicious/noExplicitAny: createFormHook env 的官方签名形态（ComponentType<any>）；禁止用于其它场景
type AnyComponent = ComponentType<any>;

// ---------------------------------------------------------------------------
// createTypedForm 工厂
// ---------------------------------------------------------------------------

export interface TypedFormEnv {
  /** 追加/覆盖字段 widget（如项目自有富文本编辑器） */
  fieldComponents?: Record<string, AnyComponent>;
  /** 追加/覆盖表单级组件 */
  formComponents?: Record<string, AnyComponent>;
}

/**
 * 组合 typed form：返回 createFormHook 全套（useAppForm / withForm / withFieldGroup /
 * useTypedAppFormContext / extendForm）。demo 与用户项目用同一 contexts → 字段上下文互通。
 */
export function createTypedForm(env: TypedFormEnv = {}) {
  return createFormHook({
    fieldContext,
    formContext,
    fieldComponents: { ...typedFieldComponents, ...env.fieldComponents },
    formComponents: { ...typedFormComponents, ...env.formComponents },
  });
}

/** 默认实例（demo 直接使用；多项目可 createTypedForm 自定义扩展） */
export const { useAppForm, withForm, extendForm } = createTypedForm();

// ---------------------------------------------------------------------------
// TypedField：component prop 风格的便利封装（v1.33 AppField 为 children render prop）
// ---------------------------------------------------------------------------

export interface TypedFieldProps {
  /** useAppForm 返回的表单实例 */
  // biome-ignore lint/suspicious/noExplicitAny: 表单实例松类型（AppField 泛型与具体表单绑定）
  form: any;
  name: string;
  /** widget 组件（如 TextWidget；或经 createTypedForm 扩展的自定义 widget） */
  component: AnyComponent;
  /** 透传给 widget 的 props（label/description/options…） */
  props?: Record<string, unknown>;
}

/**
 * `<TypedField form={form} name="env" component={SelectWidget} props={{ label: "环境", options }} />`
 * 等价 `<form.AppField name="env">{(field) => <field.SelectWidget label="环境" options={options} />}</form.AppField>`
 */
export function TypedField({ form, name, component, props }: TypedFieldProps) {
  const AppField: React.ComponentType<{
    name: string;
    children: (field: unknown) => ReactNode;
  }> = form.AppField;
  const Comp = component;
  return <AppField name={name}>{() => <Comp {...(props ?? {})} />}</AppField>;
}

// ---------------------------------------------------------------------------
// 条件显隐（visibleWhen）
// ---------------------------------------------------------------------------

export interface VisibleWhenProps {
  /** useAppForm 返回的表单实例 */
  // biome-ignore lint/suspicious/noExplicitAny: 表单实例松类型（Subscribe 泛型与具体表单绑定）
  form: any;
  /** 监听的字段名（支持嵌套 path） */
  watch: string;
  /** 值判定：true 才渲染 children */
  test: (value: unknown) => boolean;
  children: ReactNode;
}

/**
 * 条件显隐联动：`<VisibleWhen form={form} watch="env" test={(v) => v === "prod"}>…</VisibleWhen>`
 * （订阅字段值，不触发表单校验时相；隐藏字段仍在 form values 中 —— 需要「不提交隐藏值」
 * 由调用方在 onSubmit 映射时处理。）
 */
export function VisibleWhen({ form, watch, test, children }: VisibleWhenProps) {
  const Subscribe: React.ComponentType<{
    selector: (s: { values: Record<string, unknown> }) => unknown;
    children: (value: unknown) => ReactNode;
  }> = form.Subscribe;
  return (
    <Subscribe selector={(s) => readPath(s.values, watch)}>
      {(value) => (test(value) ? children : null)}
    </Subscribe>
  );
}

function readPath(values: Record<string, unknown>, path: string): unknown {
  return path.split(".").reduce<unknown>((acc, key) => {
    if (acc === null || acc === undefined) return undefined;
    if (Array.isArray(acc)) return acc[Number(key)];
    return (acc as Record<string, unknown>)[key];
  }, values);
}

export type { DateRangeValue, KvPair, UploadedFile };
