export function SelectWidget(props: SelectWidgetProps) {
  const field = useFieldContext<string>();
  const { errors } = useFieldState(field);
  return (
    <FieldShell
      label={props.label}
      description={props.description}
      required={props.required}
      errors={errors}
      className={props.className}
    >
      <Select
        value={field.state.value ?? null}
        onValueChange={(v) => field.handleChange(v === null ? "" : (v as string))}
        disabled={props.disabled}
        items={props.options}
      >
        <SelectTrigger className="w-full" aria-invalid={errors.length > 0 || undefined}>
          <SelectValue placeholder={props.placeholder ?? "请选择"} />
        </SelectTrigger>
        <SelectContent>
          {props.clearable ? (
            <SelectItem value="">
              <span className="text-muted-foreground">清除</span>
            </SelectItem>
          ) : null}
          {props.options.map((opt) => (
            <SelectItem key={opt.value} value={opt.value}>
              {opt.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>
    </FieldShell>
