  emptyText?: string;
}

/** 列表页模板（table 变体）：PageHeader + lead + FilterBar + AsyncState(DataTable) + PaginationBar + appendix */
export function ListPage({
  title,
  description,
  actions,
  lead,
  filter,
  toolbar,
  body,
  pagination,
  appendix,
  className,
}: ListPageProps) {
