// ---------------------------------------------------------------------------
// grid 变体：磁贴墙（框式缝隙 bg-muted p-0.5、色块图标、hover 箭头）
// ---------------------------------------------------------------------------

const tileColsClass: Record<NonNullable<ListPageGridProps["tileCols"]>, string> = {
  2: "sm:grid-cols-2",
  3: "sm:grid-cols-2 lg:grid-cols-3",
  4: "sm:grid-cols-2 lg:grid-cols-4",
