            <SelectContent>
              {intervalOptions.map((opt) => (
                <SelectItem key={String(opt.value)} value={opt.value === false ? "off" : opt.value}>
                  {opt.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </span>
      ) : null}
    </div>
  );
}

/**
 * resource-list-view —— L4 视图工厂（blocks 侧，docs/core-api.md §13）。
 *
 * defineResource 的文件路由一行装配：def → createResource（def 级 WeakMap 缓存）→
 * useResourceTable（def.list 配置 + def.filters + parent 参数永久过滤）→
 * ListPage + FilterBar + AsyncState + DataTable + PaginationBar。
 * 列渲染经 cellFor 消费列 meta.cell（inferColumns 的推断标记）。
 */
import type { ResourceClient, ResourceOf } from "@patterns-ui/core/data";
import { createResource } from "@patterns-ui/core/data";
import { type ListColumnDef, useResourceTable } from "@patterns-ui/core/list";
import type { ResourceDef } from "@patterns-ui/core/resource";
import { useParams, useSearch } from "@tanstack/react-router";
import { useMemo } from "react";
import { type CellForType, cellFor } from "@/components/blocks/cells/cell-for/cell-for";
import { DataTable } from "@/components/blocks/list/data-table/data-table";
import { FilterBar } from "@/components/blocks/list/filter-bar/filter-bar";
import { ListPage, ListPageGrid } from "@/components/blocks/list/list-page/list-page";
import { PaginationBar } from "@/components/blocks/list/pagination-bar/pagination-bar";
import { AsyncState } from "@/components/blocks/shared/async-state/async-state";

/** L4 视图工厂的行约束（与 core ResourceDef<TData extends RowData> 的泛型边界对齐） */
// biome-ignore lint/suspicious/noExplicitAny: ResourceDef 泛型边界形态（core-api §13）；仅作约束，禁止在实现体内新开 any
type AnyRow = Record<string, any>;

/** def → Resource 实例缓存（同一 def 复用；hooks 身份稳定） */
const resourceCache = new WeakMap<
  ResourceClient<unknown, unknown, unknown>,
  ResourceOf<Record<string, unknown>>
>();

export function resourceOf<TData extends AnyRow>(def: ResourceDef<TData>): ResourceOf<TData> {
  const client = def.client as unknown as ResourceClient<unknown, unknown, unknown>;
  let cached = resourceCache.get(client) as ResourceOf<TData> | undefined;
  if (cached === undefined) {
    cached = createResource<TData>({
      name: def.name,
      client: def.client,
      tenantScoped: def.tenantScoped !== false,
    });
    resourceCache.set(client, cached as unknown as ResourceOf<Record<string, unknown>>);
  }
  return cached;
}

/** meta.cell（inferColumns 产出）→ cellFor 类型（enum → enum-badge） */
function cellTypeOf(metaCell: string | undefined): CellForType | undefined {
  if (metaCell === undefined) return undefined;
  if (metaCell === "enum") return "enum-badge";
  if (
    [
      "id",
      "time",
      "status",
      "user",
      "boolean",
      "number",
      "enum-badge",
      "tags",
      "progress",
    ].includes(metaCell)
  ) {
    return metaCell as CellForType;
  }
  return undefined;
}

/** 列定义装饰：meta.cell → cellFor 渲染（无标记列保持原样） */
export function decorateColumns<TData extends AnyRow>(
  columns: ListColumnDef<TData>[],
): ListColumnDef<TData>[] {
  return columns.map((column) => {
    const meta = column.meta as { cell?: string; enumValues?: string[] } | undefined;
    const type = cellTypeOf(meta?.cell);
    if (type === undefined) return column;
    const options =
      type === "enum-badge" && meta?.enumValues
        ? {
            options: meta.enumValues.map((value) => ({
              value,
              variant: "secondary" as const,
            })),
          }
        : undefined;
    const CellComponent = cellFor(type, options);
    return {
      ...column,
      cell: (ctx: { getValue(): unknown }) => <CellComponent value={ctx.getValue()} />,
    } as ListColumnDef<TData>;
  });
}

export interface ResourceListViewProps<TData extends AnyRow> {
  def: ResourceDef<TData>;
  /** 展示变体（默认 table；grid = 磁贴墙，标题取 name/title/id 字段） */
  variant?: "table" | "grid";
  /** 页头副标题（产品说明文案；缺省无） */
  description?: string;
  /** 页头右侧动作（新建按钮等） */
  actions?: React.ReactNode;
  /** DataTable 附加高级模式 props（grouping/tree/aggregates/inline/virtual/mobile 透传） */
  tableProps?: Omit<React.ComponentProps<typeof DataTable<TData>>, "table" | "preferencesKey">;
  preferencesKey?: string;
  /** 列表页脚注 */
  appendix?: React.ReactNode;
  className?: string;
}

export function ResourceListView<TData extends AnyRow>({
  def,
  variant = "table",
  description,
  actions,
  tableProps,
  preferencesKey,
  appendix,
  className,
}: ResourceListViewProps<TData>) {
  const resource = useMemo(() => resourceOf(def), [def]);
  const columns = useMemo(() => decorateColumns(def.columns), [def.columns]);
  // 租户前缀（/t/:tenantId/... 布局下取当前参数；磁贴/详情链接拼绝对路径）
  const params = useParams({ strict: false }) as { tenantId?: string };
  const tenantPrefix = params.tenantId !== undefined ? `/t/${params.tenantId}` : "";

  // 子资源：parent 参数（如 ?serviceId=svc-1）→ 永久过滤（进请求不进可见 filter UI）
  const search = useSearch({ strict: false }) as Record<string, unknown>;
  const parentValue =
    def.parent && typeof search[def.parent.param] === "string"
      ? (search[def.parent.param] as string)
      : undefined;
  const permanentFilters = useMemo(
    () =>
      parentValue !== undefined && def.parent
        ? { field: def.parent.param, op: "eq" as const, value: parentValue }
        : undefined,
    [parentValue, def.parent],
  );

  const list = useResourceTable<TData>({
    resource,
    mode: def.list?.mode ?? "server-offset",
    columns,
    filters: def.filters,
    facets: def.list?.facets,
    search: { enabled: true },
    pagination: def.list?.pageSize ? { initialPageSize: def.list.pageSize } : undefined,
    permanentFilters,
  });

  const rows = list.table.getRowModel().rows.map((row) => row.original);
  const rowsEmpty = rows.length === 0;
  const hasActiveFilters = list.state.filters !== undefined || list.state.search !== "";

  const gridTiles = useMemo(() => {
    if (variant !== "grid") return [];
    return rows.map((row) => {
      const record = row as Record<string, unknown>;
      const title = String(record.name ?? record.title ?? record.id ?? "");
      return {
        title,
        description: record.description !== undefined ? String(record.description) : undefined,
        to:
          record.id !== undefined
            ? `${tenantPrefix}${listPathOf(def)}/${encodeURIComponent(String(record.id))}`
            : undefined,
      };
    });
  }, [variant, rows, def, tenantPrefix]);

  const listMode = def.list?.mode ?? "server-offset";

  return (
    <ListPage
      title={def.label ?? def.name}
      description={
        def.parent && parentValue !== undefined
          ? `${def.parent.resource}/${parentValue} 的 ${def.label ?? def.name}`
          : description
      }
      actions={actions}
      filter={
        def.filters && def.filters.length > 0 ? (
          <FilterBar list={list} defs={def.filters} onRefresh={() => void list.query.refetch()} />
        ) : undefined
      }
      body={
        variant === "grid" ? (
          <ListPageGrid title={def.label ?? def.name} tiles={gridTiles} body={null} />
        ) : (
          <AsyncState
            query={list.query}
            rowsEmpty={rowsEmpty}
            hasActiveFilters={hasActiveFilters}
            onClearFilters={() => list.reset()}
            empty={{ title: `暂无${def.label ?? def.name}`, description: "创建第一个记录开始。" }}
          >
            <DataTable
              table={list.table}
              preferencesKey={preferencesKey ?? def.name}
              mobile="cards"
              {...tableProps}
            />
          </AsyncState>
        )
      }
      pagination={
        listMode === "server-cursor" || listMode === "load-more" ? (
          <PaginationBar
            list={{
              ...list,
              hasNextPage: list.query.data?.nextCursor !== undefined || listMode === "load-more",
            }}
            mode={listMode === "server-cursor" ? "cursor" : "load-more"}
          />
        ) : (
          <PaginationBar list={list} mode="offset" />
        )
      }
      appendix={appendix}
      className={className}
    />
  );
}

/** 资源列表路径（相对租户根；宿主文件路由与 def.name 约定一致） */
// biome-ignore lint/suspicious/noExplicitAny: 与 ResourceDef 泛型形态一致（RowData 约束下 unknown 不协变）
export function listPathOf(def: ResourceDef<any>): string {
  return `/${def.name}`;
}

import { useSavedViews } from "@patterns-ui/core/list";
import { cn } from "cn";
import { Bookmark, BookmarkCheck, Pencil, Plus, Star, Trash2 } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Input } from "@/components/ui/input";

export interface SavedViewsMenuProps {
  /** 命名视图存储 key（localStorage 'fc:view:<resourceKey>'） */
  resourceKey: string;
  className?: string;
}

/** 命名视图下拉：保存当前查询串 / 应用 / 重命名 / 删除（core useSavedViews） */
export function SavedViewsMenu({ resourceKey, className }: SavedViewsMenuProps) {
  const { views, save, apply, remove, update } = useSavedViews(resourceKey);
  const [saving, setSaving] = useState(false);
  const [name, setName] = useState("");
  const [renamingId, setRenamingId] = useState<string | null>(null);
  const [renameValue, setRenameValue] = useState("");
  const nameRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (saving) nameRef.current?.focus();
  }, [saving]);

  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button variant="outline" size="sm" className={className} />}>
        <Star data-icon="inline-start" />
        视图
        {views.length > 0 ? (
          <span className="bg-muted text-muted-foreground ml-1 rounded-full px-1.5 text-[11px] tabular-nums">
            {views.length}
          </span>
        ) : null}
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-64">
        <DropdownMenuGroup>
          <DropdownMenuLabel>命名视图</DropdownMenuLabel>

          {saving ? (
            <div className="flex items-center gap-1.5 px-2 py-1.5">
              <Input
                ref={nameRef}
                value={name}
                placeholder="视图名称…"
                className="h-7"
                onChange={(e) => setName((e.target as HTMLInputElement).value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && name.trim() !== "") {
                    save(name.trim());
                    setName("");
                    setSaving(false);
                  }
                  if (e.key === "Escape") setSaving(false);
                }}
              />
              <Button
                size="xs"
                disabled={name.trim() === ""}
                onClick={() => {
                  save(name.trim());
                  setName("");
                  setSaving(false);
                }}
              >
                保存
              </Button>
            </div>
          ) : (
            <DropdownMenuItem onClick={() => setSaving(true)}>
              <Plus />
              保存当前视图…
            </DropdownMenuItem>
          )}

          {views.length > 0 ? <DropdownMenuSeparator /> : null}
          {views.map((view) =>
            renamingId === view.id ? (
              <div key={view.id} className="flex items-center gap-1.5 px-2 py-1.5">
                <Input
                  autoFocus
                  value={renameValue}
                  className="h-7"
                  onChange={(e) => setRenameValue((e.target as HTMLInputElement).value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter" && renameValue.trim() !== "") {
                      update(view.id, renameValue.trim());
                      setRenamingId(null);
                    }
                    if (e.key === "Escape") setRenamingId(null);
                  }}
                />
                <Button
                  size="xs"
                  disabled={renameValue.trim() === ""}
                  onClick={() => {
                    update(view.id, renameValue.trim());
                    setRenamingId(null);
                  }}
                >
                  确定
                </Button>
              </div>
            ) : (
              <div key={view.id} className="group/view flex items-center">
                <DropdownMenuItem
                  className="flex-1"
                  onClick={() => {
                    apply(view);
                  }}
                >
                  <Bookmark />
                  <span className="truncate">{view.name}</span>
                </DropdownMenuItem>
                <span
                  className={cn("flex items-center pr-1 opacity-0 group-hover/view:opacity-100")}
                >
                  <button
                    type="button"
                    aria-label="重命名"
                    className="text-muted-foreground hover:text-foreground rounded p-1"
                    onClick={(e) => {
                      e.preventDefault();
                      e.stopPropagation();
                      setRenamingId(view.id);
                      setRenameValue(view.name);
                    }}
                  >
                    <Pencil className="size-3" />
                  </button>
                  <button
                    type="button"
                    aria-label="删除"
                    className="text-muted-foreground hover:text-status-danger rounded p-1"
                    onClick={(e) => {
                      e.preventDefault();
                      e.stopPropagation();
                      remove(view.id);
                    }}
                  >
                    <Trash2 className="size-3" />
                  </button>
                </span>
              </div>
            ),
          )}

          {views.length > 0 ? (
            <>
              <DropdownMenuSeparator />
              <p className="text-muted-foreground flex items-center gap-1.5 px-2 py-1 text-xs">
                <BookmarkCheck className="size-3" />
                视图保存的是 URL 查询段（过滤/排序/分页）
              </p>
            </>
          ) : null}
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import { cn } from "cn";
import type { LucideIcon } from "lucide-react";
import { Trash2, X } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { Button } from "@/components/ui/button";

export interface SelectionAction {
  label: string;
  icon?: LucideIcon;
  /** 危险动作（红色按钮） */
  danger?: boolean;
  /** 需要二次确认（按钮就地变为「确认 …」，3s 未确认自动复原） */
  confirm?: boolean | string;
  run: () => void | Promise<void>;
}

export interface SelectionBarProps {
  count: number;
  actions: SelectionAction[];
  onClear: () => void;
  className?: string;
}

/** 批量操作条：已选 N + 动作组（confirm 动作两段式确认）+ 清除选择 */
export function SelectionBar({ count, actions, onClear, className }: SelectionBarProps) {
  if (count === 0) return null;
  return (
    <div
      className={cn(
        "bg-primary/5 border-primary/20 flex flex-wrap items-center gap-2 rounded-lg border px-3 py-2",
        className,
      )}
      data-slot="selection-bar"
      role="toolbar"
      aria-label="批量操作"
    >
      <span className="text-primary text-[13px] font-medium tabular-nums">已选 {count} 项</span>
      <span className="bg-border h-4 w-px" aria-hidden />
      {actions.map((action) => (
        <SelectionActionButton key={action.label} action={action} />
      ))}
      <Button variant="ghost" size="sm" className="ml-auto" onClick={onClear} aria-label="清除选择">
        <X data-icon="inline-start" />
        清除
      </Button>
    </div>
  );
}

function SelectionActionButton({ action }: { action: SelectionAction }) {
  const [confirming, setConfirming] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined);
  const Icon = action.icon ?? (action.danger ? Trash2 : undefined);

  useEffect(() => {
    return () => {
      if (timer.current !== undefined) clearTimeout(timer.current);
    };
  }, []);

  const needsConfirm = action.confirm !== undefined;
  const confirmText = typeof action.confirm === "string" ? action.confirm : action.label;

  if (confirming) {
    return (
      <Button
        size="sm"
        variant={action.danger ? "destructive" : "default"}
        onClick={() => {
          setConfirming(false);
          void action.run();
        }}
      >
        确认{confirmText}？
      </Button>
    );
  }

  return (
    <Button
      size="sm"
      variant={action.danger ? "destructive" : "outline"}
      onClick={() => {
        if (needsConfirm) {
          setConfirming(true);
          timer.current = setTimeout(() => setConfirming(false), 3000);
          return;
        }
        void action.run();
      }}
    >
      {Icon ? <Icon data-icon="inline-start" /> : null}
      {action.label}
    </Button>
  );
}

import type { BulkResult, MutationOpts, Resource } from "@patterns-ui/core/data";
import type { UndoableToastControl } from "@patterns-ui/core/mutation";
import { cn } from "cn";
import { useEffect, useRef, useState } from "react";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";

export interface UseResourceMutationsOptions {
  /** undoable 倒计时（ms），默认 5000 */
  undoDurationMs?: number;
  /** 单项操作成功提示开关（默认开；bulk 结果汇总恒开） */
  successToast?: boolean;
}

function summarize(label: string, result: BulkResult | undefined): void {
  if (!result) {
    toast.success(`${label}完成`);
    return;
  }
  const { succeeded, failed } = result;
  if (failed.length === 0) toast.success(`${label}完成（${succeeded.length} 项）`);
  else toast.warning(`${label}：成功 ${succeeded.length}，失败 ${failed.length}`);
}

/** undoable toast 视图：自带每秒倒数；toast 只渲染一次（重发 upsert 会触发 onDismiss → 意外立即提交） */
function UndoableToastView({
  ctl,
  initialSeconds,
  onClose,
  className,
}: {
  ctl: UndoableToastControl;
  initialSeconds: number;
  onClose: () => void;
  className?: string;
}) {
  const [secondsLeft, setSecondsLeft] = useState(initialSeconds);
  useEffect(() => {
    const timer = setInterval(() => {
      setSecondsLeft((s) => (s > 0 ? s - 1 : 0));
    }, 1000);
    return () => clearInterval(timer);
  }, []);
  return (
    <div
      data-slot="undoable-toast"
      className={cn(
        "bg-popover text-popover-foreground pointer-events-auto flex w-full items-center justify-between gap-4 rounded-lg border px-4 py-3 shadow-lg",
        className,
      )}
    >
      <p className="text-sm">
        已应用变更，<span className="tabular-nums">{secondsLeft}</span>s 内可撤销
      </p>
      <Button
        size="sm"
        variant="outline"
        onClick={() => {
          ctl.undo();
          onClose();
        }}
      >
        撤销（{secondsLeft}s）
      </Button>
    </div>
  );
}

/**
 * createResource 消费层的 toast 接线（宿主侧惯例 helper，放 registry 便于 copy-paste）：
 * 把 undoable 档的 onUndoableToast 接到 sonner —— 倒计时 Undo 按钮；用户提前关闭 toast
 * 视为已确认（立即提交）。core 只发事件不含 UI。
 *
 * 注意：mutation opts 经 ref 惰性创建一次（每次 render 重建会换 key，undo 标记对不上 onSuccess）。
 *
 * 用法：组件内 `const { useDeleteWithUndo } = useResourceMutations(resource);`
 * 然后与普通 hook 一样调用 `const del = useDeleteWithUndo(); del.mutate({ id })`。
 */
export function useResourceMutations<TData, TCreate, TUpdate>(
  resource: Resource<TData, TCreate, TUpdate>,
  options: UseResourceMutationsOptions = {},
) {
  const { undoDurationMs = 5000, successToast = true } = options;
  /** undo 标记：key 在 opts 首次创建时固定（见上） */
  const undoneFlags = useRef(new Map<string, boolean>());
  const seq = useRef(0);

  const deleteOptsRef = useRef<MutationOpts<{ id: string }> | null>(null);
  const bulkDeleteOptsRef = useRef<MutationOpts<{ ids: string[] }> | null>(null);

  const makeUndoableOpts = <TVars,>(key: string, successMessage: string): MutationOpts<TVars> => {
    let toastShown = false;
    return {
      mutationMode: "undoable",
      undoDurationMs,
      onUndoableToast: (rawCtl: UndoableToastControl) => {
        if (toastShown) {
          // 后续每秒回调只驱动 core 侧时序，不再重发 toast（upsert 会误触发 onDismiss）
          return;
        }
        toastShown = true;
        const ctl: UndoableToastControl = {
          ...rawCtl,
          undo: () => {
            undoneFlags.current.set(key, true);
            rawCtl.undo();
            toast.info("已撤销，未提交变更");
          },
        };
        toast.custom(
          (t) => (
            <UndoableToastView
              ctl={ctl}
              initialSeconds={ctl.secondsLeft}
              onClose={() => toast.dismiss(t)}
            />
          ),
          {
            duration: undoDurationMs + 500,
            onDismiss: () => {
              // 用户提前关掉 toast = 已知晓 → 立即提交（与超时等价；超时后此处 no-op）
              ctl.dismiss();
            },
          },
        );
      },
      onSuccess: () => {
        if (undoneFlags.current.get(key)) {
          undoneFlags.current.delete(key);
          return;
        }
        if (successToast) toast.success(successMessage);
      },
    };
  };

  return {
    /** undoable 删除：行立即消失 + toast 倒计时撤销恢复 */
    useDeleteWithUndo: () => {
      if (deleteOptsRef.current === null) {
        seq.current += 1;
        deleteOptsRef.current = makeUndoableOpts<{ id: string }>(`del-${seq.current}`, "已删除");
      }
      return resource.useDelete(deleteOptsRef.current);
    },
    /** undoable 批量删除（SelectionBar 动作接它）；结果汇总 成功 N 失败 M */
    useBulkDeleteWithUndo: () => {
      if (bulkDeleteOptsRef.current === null) {
        seq.current += 1;
        const key = `bulk-del-${seq.current}`;
        bulkDeleteOptsRef.current = {
          ...makeUndoableOpts<{ ids: string[] }>(key, "批量删除"),
          onSuccess: (data) => summarize("批量删除", data as BulkResult | undefined),
        };
      }
      return resource.useBulkDelete(bulkDeleteOptsRef.current);
    },
    /** 悲观批量更新（结果汇总） */
    useBulkUpdate: () =>
      resource.useBulkUpdate({
        onSuccess: (data) => summarize("批量更新", data as BulkResult | undefined),
      }),
  };
}

