/**
 * danger-zone —— 危险操作区（底部红框卡 + 动作列表 + confirm 接线）。
 * 确认交互经 confirm-dialog block（普通/type-to-confirm）由本组件内部编排。
 */
import { AlertOctagon } from "lucide-react";
import { type ReactNode, useState } from "react";
import { ConfirmDialog } from "@/components/blocks/form/confirm-dialog/confirm-dialog";
import { Button } from "@/components/ui/button";

export interface DangerAction {
  label: ReactNode;
  description?: ReactNode;
  /** 高危变体：输入该名称才允许确认 */
  typeToConfirm?: string;
  typeToConfirmLabel?: string;
  confirmLabel?: string;
  danger?: boolean;
  pending?: boolean;
  /** 确认后执行（danger-zone 内部弹 confirm） */
  run: () => void | Promise<void>;
  /** 覆盖右侧按钮渲染（如需要异步状态） */
  renderTrigger?: (open: () => void) => ReactNode;
}

export interface DangerZoneProps {
  title?: ReactNode;
  description?: ReactNode;
  actions: DangerAction[];
}

/** 红框卡：danger 语义 token（--status-danger），动作逐行 + 右侧触发按钮。 */
export function DangerZone({
  title = "危险操作区",
  description = "以下操作不可撤销，请确认后再执行。",
  actions,
}: DangerZoneProps) {
  const [activeIndex, setActiveIndex] = useState<number | null>(null);
  const active = activeIndex !== null ? actions[activeIndex] : undefined;

  return (
    <section className="border-status-danger/40 rounded-xl border">
      <header className="border-status-danger/40 flex items-start gap-2.5 border-b px-5 py-4">
        <AlertOctagon className="text-status-danger mt-0.5 size-4 shrink-0" />
        <div>
          <h2 className="text-status-danger text-sm font-medium">{title}</h2>
          <p className="text-muted-foreground text-sm">{description}</p>
        </div>
      </header>
      <ul className="divide-border divide-y">
        {actions.map((action, index) => (
          <li key={index} className="flex flex-wrap items-center justify-between gap-3 px-5 py-4">
            <div className="min-w-0">
              <p className="text-sm font-medium">{action.label}</p>
              {action.description ? (
                <p className="text-muted-foreground mt-0.5 text-sm">{action.description}</p>
              ) : null}
            </div>
            {action.renderTrigger ? (
              action.renderTrigger(() => setActiveIndex(index))
            ) : (
              <Button
                type="button"
                variant="destructive"
                size="sm"
                disabled={action.pending}
                onClick={() => setActiveIndex(index)}
              >
                {action.confirmLabel ?? "执行"}
              </Button>
            )}
          </li>
        ))}
      </ul>

      {active ? (
        <ConfirmDialog
          open={activeIndex !== null}
          onOpenChange={(open) => {
            if (!open) setActiveIndex(null);
          }}
          danger={active.danger !== false}
          title={active.label}
          description={active.description}
          typeToConfirm={active.typeToConfirm}
          typeToConfirmLabel={active.typeToConfirmLabel}
          confirmLabel={active.confirmLabel ?? "确认执行"}
          pending={active.pending}
          onConfirm={async () => {
            try {
              await active.run();
            } finally {
              setActiveIndex(null);
            }
          }}
        />
      ) : null}
    </section>
  );
}

/**
 * detail-grid —— 键值两列区（值经 cells 渲染）。
 */
import { cn } from "cn";
import type { ReactNode } from "react";
import {
  type CellForOptions,
  type CellForType,
  cellFor,
} from "@/components/blocks/cells/cell-for/cell-for";

export interface DetailGridItem {
  label: string;
  /** 取值字段名（从 data 读取） */
  field: string;
  /** cells 渲染器类型（缺省原样输出） */
  cell?: CellForType;
  /** cell 渲染选项（cellFor 参数） */
  cellOptions?: CellForOptions;
  /** 完全自定义渲染（优先于 cell） */
  render?: (value: unknown, data: Record<string, unknown>) => ReactNode;
  /** 值为空时占位 */
  fallback?: ReactNode;
}

export interface DetailGridProps {
  items: DetailGridItem[];
  data: Record<string, unknown> | undefined;
  /** 列数（1-3，默认 2） */
  columns?: 1 | 2 | 3;
  title?: string;
  description?: string;
  className?: string;
}

const columnClass = {
  1: "sm:grid-cols-1",
  2: "sm:grid-cols-2",
  3: "sm:grid-cols-3",
} as const;

/** 键值两列网格：label 上、值下；值经 cellFor(cells) 渲染或 render 自定义。 */
export function DetailGrid({
  items,
  data,
  columns = 2,
  title,
  description,
  className,
}: DetailGridProps) {
  const cellCache = new Map<string, ReturnType<typeof cellFor>>();
  return (
    <section className={cn("space-y-4", className)}>
      {title ? (
        <div>
          <h2 className="text-sm font-medium">{title}</h2>
          {description ? <p className="text-muted-foreground text-sm">{description}</p> : null}
        </div>
      ) : null}
      <dl className={cn("grid grid-cols-1 gap-x-8 gap-y-5", columnClass[columns])}>
        {items.map((item) => {
          const value = data ? data[item.field] : undefined;
          const empty = value === undefined || value === null || value === "";
          let content: ReactNode;
          if (item.render) {
            content = item.render(value, data ?? {});
          } else if (item.cell) {
            if (!cellCache.has(item.cell)) {
              cellCache.set(item.cell, cellFor(item.cell, item.cellOptions));
            }
            const CellComponent = cellCache.get(item.cell) as React.ComponentType<{
              value: unknown;
            }>;
            content = <CellComponent value={value} />;
          } else {
            content = empty ? null : <span className="text-sm break-all">{String(value)}</span>;
          }
          return (
            <div key={item.field + item.label} className="space-y-1">
              <dt className="text-muted-foreground text-xs font-medium tracking-wider uppercase">
                {item.label}
              </dt>
              <dd className="text-foreground text-sm">
                {empty && !item.render ? (
                  <span className="text-muted-foreground/70">{item.fallback ?? "—"}</span>
                ) : (
                  content
                )}
              </dd>
            </div>
          );
        })}
      </dl>
    </section>
  );
}

