      <header className="flex flex-wrap items-start justify-between gap-4">
        <div className="flex min-w-0 items-start gap-3">
          {heroMeta?.visual ? (
            <div className="bg-muted text-muted-foreground flex size-12 shrink-0 items-center justify-center rounded-xl border">
              {heroMeta.visual}
            </div>
          ) : Icon ? (
            <div className="bg-muted text-muted-foreground flex size-12 shrink-0 items-center justify-center rounded-xl border">
              <Icon className="size-5" />
            </div>
          ) : null}
          <div className="min-w-0 space-y-1.5">
            <div className="flex flex-wrap items-center gap-2.5">
              <h1 className="truncate text-2xl font-semibold tracking-tight">{title}</h1>
              {status ? (
                <StatusBadge tone={status.tone} pulse={status.pulse}>
                  {status.label}
                </StatusBadge>
              ) : null}
              {heroMeta?.badges}
            </div>
            {heroMeta?.subtitle ? (
              <p className="text-muted-foreground font-mono text-xs">{heroMeta.subtitle}</p>
            ) : null}
          </div>
        </div>
        {actions ? <div className="flex flex-wrap items-center gap-2">{actions}</div> : null}
      </header>

      {lead}

      {/* tabs（受控：深链由页面经 useDetailTabParam 接线） */}
      <Tabs value={current} onValueChange={(v) => onTabChange?.(v as string)}>
        <TabsList className="w-full justify-start overflow-x-auto">
          {tabs.map((tab) => (
            <TabsTrigger key={tab.id} value={tab.id}>
              {tab.label}
              {tab.badge !== undefined ? (
                <span className="text-muted-foreground ml-1.5 text-xs">{tab.badge}</span>
              ) : null}
            </TabsTrigger>
          ))}
        </TabsList>
        {tabs.map((tab) => (
          <TabsContent key={tab.id} value={tab.id} className="mt-4">
            {tab.content}
          </TabsContent>
        ))}
      </Tabs>
    </div>
  );
}

/**
 * tab 深链胶水：URL search 参数 `tab` 读写（保留其余 search 参数，如来源列表过滤）。
 *
 * ```tsx
 * const { activeTab, setTab } = useDetailTabParam()
 * <DetailPage tabs={...} activeTab={activeTab} onTabChange={setTab} />
 * ```
 */
export function useDetailTabParam(defaultTab: string, searchKey = "tab") {
  const navigate = useNavigate();
  const raw = useRouterState({
    select: (s) => {
      const value = (s.location.search as Record<string, unknown>)[searchKey];
      return typeof value === "string" && value !== "" ? value : undefined;
    },
  });
  const activeTab = raw ?? defaultTab;
  const setTab = (id: string) => {
    if (id === activeTab) return;
    void navigate({
      to: ".",
      search: (prev: Record<string, unknown>) => ({
        ...prev,
        [searchKey]: id === defaultTab ? undefined : id,
      }),
    } as never);
  };
  return { activeTab, setTab };
}

/**
 * diff-viewer —— JSON 树 diff + 行 diff 两模式（删除/新增/变更三色语义走 status token）。
 */
import { cn } from "cn";
import { useMemo, useState } from "react";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";

export type DiffOp = "added" | "removed" | "changed" | "unchanged";

export interface DiffEntry {
  /** 点路径（a.b.0.c） */
  path: string;
  op: DiffOp;
  before?: unknown;
  after?: unknown;
}

const opBadge: Record<DiffOp, { label: string; cls: string }> = {
  added: { label: "新增", cls: "bg-status-success-bg text-status-success" },
  removed: { label: "删除", cls: "bg-status-danger-bg text-status-danger" },
  changed: { label: "变更", cls: "bg-status-warning-bg text-status-warning" },
  unchanged: { label: "不变", cls: "bg-muted text-muted-foreground" },
};

function stringify(value: unknown): string {
  if (value === undefined) return "—";
  if (typeof value === "string") return value;
  try {
    return JSON.stringify(value, null, 2) ?? String(value);
  } catch {
    return String(value);
  }
}

/** 扁平 diff：两对象按点路径逐键对比（数组按下标；仅报告差异项）。 */
export function diffRecords(
  before: Record<string, unknown> | undefined,
  after: Record<string, unknown> | undefined,
): DiffEntry[] {
  const out: DiffEntry[] = [];
  const walk = (b: unknown, a: unknown, path: string) => {
    const bObj = b !== null && typeof b === "object" ? (b as Record<string, unknown>) : undefined;
    const aObj = a !== null && typeof a === "object" ? (a as Record<string, unknown>) : undefined;
    if (bObj !== undefined || aObj !== undefined) {
      const keys = [...new Set([...Object.keys(bObj ?? {}), ...Object.keys(aObj ?? {})])];
      keys.sort();
      for (const key of keys) {
        walk(bObj?.[key], aObj?.[key], path === "" ? key : `${path}.${key}`);
      }
      return;
    }
    if (b === undefined && a !== undefined) {
      out.push({ path, op: "added", after: a });
    } else if (b !== undefined && a === undefined) {
      out.push({ path, op: "removed", before: b });
    } else if (JSON.stringify(b) !== JSON.stringify(a)) {
      out.push({ path, op: "changed", before: b, after: a });
    }
  };
  walk(before, after, "");
  return out;
}

export interface DiffViewerProps {
  before: unknown;
  after: unknown;
  /** 初始模式，默认 'json' */
  mode?: "json" | "lines";
  /** json 树模式是否显示未变更键（默认仅差异） */
  showUnchanged?: boolean;
  /** 空差异占位 */
  emptyLabel?: string;
  className?: string;
}

/**
 * 两版对比查看器：
 * - json 模式：diffRecords 扁平对比 → 差异行表（路径 + before/after + 三色徽标）；
 * - lines 模式：两侧字符串逐行对照（左删右增），适合长文本/JSON 序列化后对比。
 */
export function DiffViewer({
  before,
  after,
  mode = "json",
  showUnchanged = false,
  emptyLabel = "没有差异",
  className,
}: DiffViewerProps) {
  const [current, setCurrent] = useState<"json" | "lines">(mode);

  const entries = useMemo(
    () =>
      diffRecords(
        before !== null && typeof before === "object"
          ? (before as Record<string, unknown>)
          : undefined,
        after !== null && typeof after === "object"
          ? (after as Record<string, unknown>)
          : undefined,
      ),
    [before, after],
  );

  const beforeLines = useMemo(() => stringify(before).split("\n"), [before]);
  const afterLines = useMemo(() => stringify(after).split("\n"), [after]);

  return (
    <div className={cn("space-y-3", className)}>
      <Tabs value={current} onValueChange={(v) => setCurrent(v as "json" | "lines")}>
        <TabsList>
          <TabsTrigger value="json">字段对比</TabsTrigger>
          <TabsTrigger value="lines">逐行对比</TabsTrigger>
        </TabsList>
      </Tabs>

      {current === "json" ? (
        entries.length === 0 && !showUnchanged ? (
          <p className="text-muted-foreground text-sm">{emptyLabel}</p>
        ) : (
          <div className="divide-border overflow-hidden rounded-lg border">
            {entries.length === 0 ? (
              <p className="text-muted-foreground px-4 py-3 text-sm">{emptyLabel}</p>
            ) : (
              entries.map((entry) => (
                <div
                  key={entry.path}
                  className="grid grid-cols-[110px_minmax(0,1fr)] gap-x-4 gap-y-1 px-4 py-2.5 text-sm sm:grid-cols-[110px_minmax(0,2fr)_minmax(0,2fr)]"
                >
                  <span className="text-muted-foreground overflow-hidden font-mono text-xs">
                    {entry.path}
                  </span>
                  <span className="min-w-0">
                    <span
                      className={cn(
                        "mr-2 inline-block rounded px-1.5 py-0.5 text-xs font-medium",
                        opBadge[entry.op].cls,
                      )}
                    >
                      {opBadge[entry.op].label}
                    </span>
                    {entry.op === "added" ? null : (
                      <code className="text-muted-foreground block truncate font-mono text-xs strike">
                        {stringify(entry.before)}
                      </code>
                    )}
                    {entry.op === "removed" ? null : (
                      <code className="block truncate font-mono text-xs">
                        {stringify(entry.after)}
                      </code>
                    )}
                  </span>
                </div>
              ))
            )}
          </div>
        )
      ) : (
        <div className="grid grid-cols-2 overflow-hidden rounded-lg border">
          <div className="border-r">
            <div className="bg-muted/50 text-muted-foreground border-b px-3 py-1.5 text-xs font-medium">
              变更前
            </div>
            <pre className="overflow-x-auto p-3 text-xs leading-5">
              {beforeLines.map((line, i) => (
                <div
                  key={i}
                  className={cn(
                    "font-mono",
                    afterLines[i] !== undefined &&
                      afterLines[i] !== line &&
                      "bg-status-danger-bg/60 text-status-danger",
                  )}
                >
                  {line === "" ? "\u00A0" : line}
                </div>
              ))}
            </pre>
          </div>
          <div>
            <div className="bg-muted/50 text-muted-foreground border-b px-3 py-1.5 text-xs font-medium">
              变更后
            </div>
            <pre className="overflow-x-auto p-3 text-xs leading-5">
              {afterLines.map((line, i) => (
                <div
                  key={i}
                  className={cn(
                    "font-mono",
                    beforeLines[i] !== undefined &&
                      beforeLines[i] !== line &&
                      "bg-status-success-bg/60 text-status-success",
                  )}
                >
                  {line === "" ? "\u00A0" : line}
                </div>
              ))}
            </pre>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * inline-edit-field —— 点击即改字段（TriggerLink → 编辑态 → 保存/取消）。
 */
import { cn } from "cn";
import { Check, Loader2, Pencil, X } from "lucide-react";
import { useEffect, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";

export interface InlineEditFieldProps {
  value: string | number | undefined;
  /** 保存（异步）；抛错则回退显示原值（错误处理由调用方 toast） */
  onSave: (next: string) => Promise<void> | void;
  /** 编辑控件类型，默认 text */
  type?: "text" | "number";
  placeholder?: string;
  /** 空值占位（默认「点击编辑」） */
  emptyLabel?: string;
  disabled?: boolean;
  /** 展示态格式化（如数字单位） */
  format?: (value: string | number | undefined) => string;
  className?: string;
}

/** 点击即改：展示态是可点击的下划线虚线文本 → 进入编辑 → Enter/✓ 保存、Esc/✕ 取消。 */
export function InlineEditField({
  value,
  onSave,
  type = "text",
  placeholder,
  emptyLabel = "点击编辑",
  disabled = false,
  format,
  className,
}: InlineEditFieldProps) {
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState("");
  const [saving, setSaving] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (editing) inputRef.current?.focus();
  }, [editing]);

  const beginEdit = () => {
    if (disabled) return;
    setDraft(value === undefined || value === null ? "" : String(value));
    setEditing(true);
  };

  const cancel = () => {
    setEditing(false);
    setDraft("");
  };

  const save = async () => {
    setSaving(true);
    try {
      await onSave(draft);
      setEditing(false);
    } finally {
      setSaving(false);
    }
  };

  if (editing) {
    return (
      <span className={cn("inline-flex items-center gap-1.5", className)}>
        <Input
          ref={inputRef}
          type={type}
          value={draft}
          placeholder={placeholder}
          className="h-7 w-36"
          disabled={saving}
          onChange={(e) => setDraft(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              e.preventDefault();
              void save();
            } else if (e.key === "Escape") {
              e.preventDefault();
              cancel();
            }
          }}
        />
        <Button
          type="button"
          variant="ghost"
          size="icon-xs"
          aria-label="保存"
          disabled={saving}
          onClick={() => void save()}
        >
          {saving ? (
            <Loader2 className="animate-spin" />
          ) : (
            <Check className="text-status-success" />
          )}
        </Button>
        <Button
          type="button"
          variant="ghost"
          size="icon-xs"
          aria-label="取消"
          disabled={saving}
          onClick={cancel}
        >
          <X className="text-muted-foreground" />
        </Button>
      </span>
    );
  }

  const empty = value === undefined || value === null || value === "";
  return (
    <button
      type="button"
      className={cn(
        "group/inline-edit hover:border-border focus-visible:border-ring inline-flex max-w-full items-center gap-1.5 border-b border-dashed border-transparent text-left text-sm transition-colors outline-none",
        disabled ? "cursor-not-allowed opacity-60" : "cursor-pointer",
        className,
      )}
      disabled={disabled}
      onClick={beginEdit}
    >
      {empty ? (
        <span className="text-muted-foreground/70">{emptyLabel}</span>
      ) : (
        <span className="truncate">{format ? format(value) : String(value)}</span>
      )}
      {!disabled ? (
        <Pencil className="text-muted-foreground/50 group-hover/inline-edit:text-muted-foreground size-3 shrink-0 opacity-0 transition-opacity group-hover/inline-edit:opacity-100" />
      ) : null}
    </button>
  );
}

/**
 * record-pager —— 上一条/下一条（基于来源列表 query 的相邻记录）。
 * 相邻 id 取自列表 query 已加载页；导航保留来源 search（TanStack Router 相对导航）。
 */

import { useNavigate } from "@tanstack/react-router";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { useMemo } from "react";
import { Button } from "@/components/ui/button";

export interface RecordPagerProps {
  /** 来源列表的 rows（通常为 useResourceTable().query.data?.rows；已按当前排序） */
  rows: { id: string }[] | undefined;
  currentId: string | undefined;
  /**
   * 相邻记录目标路径工厂（默认当前路径替换 id 段：`..` + `/${id}`）。
   * 返回相对/绝对 path；null = 禁用跳转。
   */
  to?: (id: string) => string;
  /** 计数展示文案（默认「i / n」） */
  label?: (index: number, total: number) => string;
}

/**
 * 记录翻页：在来源列表的相邻记录间跳转（保留当前路由 search，如 tab/过滤态）。
 * 未在 rows 中找到 currentId（如深链直入）时仅展示禁用态。
 */
export function RecordPager({ rows, currentId, to, label }: RecordPagerProps) {
  const navigate = useNavigate();

  const position = useMemo(() => {
    if (rows === undefined || currentId === undefined) return undefined;
    const index = rows.findIndex((row) => row.id === currentId);
    return index < 0 ? undefined : { index, total: rows.length };
  }, [rows, currentId]);

  if (position === undefined) return null;
  const { index, total } = position;
  const prev = index > 0 ? rows?.[index - 1] : undefined;
  const next = index < total - 1 ? rows?.[index + 1] : undefined;

  const go = (row: { id: string } | undefined) => {
    if (row === undefined) return;
    const target = to ? to(row.id) : `../${encodeURIComponent(row.id)}`;
    if (target === null) return;
    void navigate({ to: target, search: true } as never);
  };

  return (
    <nav className="text-muted-foreground flex items-center gap-1.5 text-sm" aria-label="记录翻页">
      <Button
        type="button"
        variant="outline"
        size="sm"
        disabled={prev === undefined}
        aria-label="上一条"
        onClick={() => go(prev)}
      >
        <ChevronLeft /> 上一条
      </Button>
      <span className="text-foreground tabular-nums">
        {label ? label(index + 1, total) : `${index + 1} / ${total}`}
      </span>
      <Button
        type="button"
        variant="outline"
        size="sm"
        disabled={next === undefined}
        aria-label="下一条"
        onClick={() => go(next)}
      >
        下一条 <ChevronRight />
      </Button>
    </nav>
  );
}

/**
 * reference-field —— 外键显示（异步解析 label；core useReferenceLabel）。
 */

import type { ReferenceSource } from "@patterns-ui/core/reference";
import { useReferenceLabel } from "@patterns-ui/core/reference";
import type { ReactNode } from "react";
import { Skeleton } from "@/components/ui/skeleton";

export interface ReferenceFieldProps<TData = Record<string, unknown>> {
  resource: ReferenceSource<TData>;
  id: string | undefined;
  /** label 取值（默认 name ?? title ?? id） */
  getIdLabel?: (row: TData) => string;
  /** 解析失败/为空时的占位 */
  fallback?: ReactNode;
  /** 渲染自定义内容（默认纯文本） */
  render?: (label: string | undefined, row: TData | undefined) => ReactNode;
}

/** 外键 → 异步 label（共享 useReference 缓存：同 id 多处只解析一次）。 */
export function ReferenceField<TData = Record<string, unknown>>({
  resource,
  id,
  getIdLabel,
  fallback,
  render,
}: ReferenceFieldProps<TData>) {
  const enabled = id !== undefined && id !== "";
  const { labels, isLoading, data } = useReferenceLabel(resource, enabled ? [id] : [], getIdLabel);
  if (!enabled) return <span className="text-muted-foreground/70">{fallback ?? "—"}</span>;
  if (isLoading) return <Skeleton className="h-4 w-24" />;
  const label = labels[id as string];
  if (render) return <>{render(label, data[id as string])}</>;
  if (label === undefined)
    return <span className="text-muted-foreground/70">{fallback ?? id}</span>;
  return <span>{label}</span>;
}

/**
 * resource-detail-view —— L4 详情视图工厂（blocks 侧，docs/core-api.md §13）。
 *
 * def + id → resourceOf(def).useOne（loader 已预取 → 命中缓存）→ DetailPage 装配：
 * hero（名称 + id 副标题 + def.show 状态列）+ tabs（sections / sub-resource 占位 / custom render）。
 * sections 的 cell 类型经 cellFor 渲染（与 inferColumns 同一标记体系）。
 */

import type { ResourceDef } from "@patterns-ui/core/resource";
import { useMemo } from "react";
import {
  listPathOf,
  resourceOf,
} from "@/components/blocks/list/resource-list-view/resource-list-view";
import { ErrorState } from "@/components/blocks/shared/error-state/error-state";
import { DetailGrid, type DetailGridItem } from "@/components/blocks/show/detail-grid/detail-grid";
import { DetailPage, useDetailTabParam } from "@/components/blocks/show/detail-page/detail-page";
import { Skeleton } from "@/components/ui/skeleton";

/** L4 详情工厂的行约束（与 ResourceDef<TData extends RowData> 的泛型边界对齐） */
// biome-ignore lint/suspicious/noExplicitAny: ResourceDef 泛型边界形态（core-api §13）；仅作约束，禁止在实现体内新开 any
type AnyRow = Record<string, any>;

export interface ResourceDetailViewProps<TData extends AnyRow> {
  def: ResourceDef<TData>;
  id: string;
  /** 详情路由的相对返回前缀（默认 '../../'：/services/svc-1 → ../..；宿主按路由层级给） */
  backPrefix?: string;
  /** 状态字段名（值经 status map 渲染；缺省不显示状态） */
  statusField?: string;
  /** 状态值 → tone 映射 */
  statusMap?: Record<string, "success" | "warning" | "danger" | "info" | "neutral">;
  /** custom tab 渲染器（tab.kind === 'custom' 时调用） */
  renderCustomTab?: (tabId: string, row: TData) => React.ReactNode;
  /** hero 右侧动作 */
  actions?: React.ReactNode;
  className?: string;
}

export function ResourceDetailView<TData extends AnyRow>({
  def,
  id,
  backPrefix = "../../",
  statusField,
  statusMap,
  renderCustomTab,
  actions,
  className,
}: ResourceDetailViewProps<TData>) {
  const resource = useMemo(() => resourceOf(def), [def]);
  const query = resource.useOne(id);
  const { activeTab, setTab } = useDetailTabParam("overview");

  const sections = def.show?.sections ?? [];
  const tabs = def.show?.tabs;

  if (query.isError) {
    return (
      <div className="mx-auto w-full max-w-5xl">
        <ErrorState
          error={query.error instanceof Error ? query.error : new Error("加载失败")}
          onRetry={() => void query.refetch()}
        />
      </div>
    );
  }

  const row = query.data;
  if (row === undefined) {
    return (
      <div className="mx-auto w-full max-w-5xl space-y-4">
        <Skeleton className="h-6 w-40" />
        <Skeleton className="h-16 w-full" />
        <Skeleton className="h-64 w-full" />
      </div>
    );
  }

  const record = row as Record<string, unknown>;
  const title = String(record.name ?? record.title ?? record.id ?? id);
  const listPath = listPathOf(def);

  const gridItemsFor = (sectionIndex: number): DetailGridItem[] =>
    (sections[sectionIndex]?.items ?? []).map((item) => ({
      label: item.label,
      field: item.field,
      // DetailGrid cell 类型与 inferColumns 的 meta.cell 共用（enum → enum-badge）
      cell: item.cell === "enum" ? ("enum-badge" as const) : (item.cell as DetailGridItem["cell"]),
      cellOptions: {
        options:
          item.cell === "enum" || item.cell === "enum-badge"
            ? enumOptionsOf(def, item.field)
            : undefined,
      },
    }));

  const detailTabs =
    tabs && tabs.length > 0
      ? tabs.map((tab, i) => ({
          id: tab.id,
          label: tab.label,
          content:
            tab.kind === "sections" ? (
              <section className="bg-card text-card-foreground rounded-xl border p-6">
                <DetailGrid
                  title={sections[i]?.title ?? tab.label}
                  data={record}
                  items={gridItemsFor(i)}
                />
              </section>
            ) : tab.kind === "custom" ? (
              (renderCustomTab?.(tab.id, row) ?? (
                <p className="text-muted-foreground text-sm">
                  自定义 tab（renderCustomTab 未提供）
                </p>
              ))
            ) : (
              <p className="text-muted-foreground bg-card rounded-xl border p-6 text-sm">
                子资源 {tab.resource ?? ""}（由宿主以 sub-resource tab 装配，如 deployments）
              </p>
            ),
        }))
      : sections.length > 0
        ? [
            {
              id: "overview",
              label: "概览",
              content: (
                <section className="bg-card text-card-foreground rounded-xl border p-6">
                  <DetailGrid title={sections[0]?.title} data={record} items={gridItemsFor(0)} />
                </section>
              ),
            },
          ]
        : [
            {
              id: "overview",
              label: "概览",
              content: (
                <section className="bg-card text-card-foreground rounded-xl border p-6">
                  <DetailGrid
                    data={record}
                    items={Object.keys(record)
                      .filter((field) => field !== "version")
                      .map((field) => ({ label: field, field }))}
                  />
                </section>
              ),
            },
          ];

  const statusValue = statusField !== undefined ? String(record[statusField] ?? "") : undefined;
  const statusTone =
    statusValue !== undefined && statusMap !== undefined
      ? (statusMap[statusValue] ?? "neutral")
      : undefined;

  return (
    <DetailPage
      className={className}
      title={title}
      heroMeta={{ subtitle: String(record.id ?? id) }}
      status={
        statusValue !== undefined && statusTone !== undefined
          ? { tone: statusTone, label: statusValue }
          : undefined
      }
      actions={actions}
      backTo={{ to: `${backPrefix}${listPath.replace(/^\//, "")}`, label: def.label ?? def.name }}
      activeTab={activeTab}
      onTabChange={setTab}
      tabs={detailTabs}
    />
  );
}

/** 从列定义 meta.enumValues 取某字段的枚举选项（cell-enum-badge 用） */
function enumOptionsOf<TData extends AnyRow>(
  def: ResourceDef<TData>,
  field: string,
): { value: string; variant: "secondary" }[] | undefined {
  const column = def.columns.find((c) => c.id === field);
  const meta = column?.meta as { enumValues?: string[] } | undefined;
  return meta?.enumValues?.map((value) => ({ value, variant: "secondary" as const }));
}

/**
 * timeline —— 事件时间线（三态：done/running/waiting；docs/blocks.md show/）。
 */

import {
  formatAbsolute,
  formatRelative,
  useDateTimePrefs,
} from "@patterns-ui/core/datetime";
import { cn } from "cn";
import { Check, Loader2 } from "lucide-react";
import type { ReactNode } from "react";

export type TimelineItemState = "done" | "running" | "waiting" | "failed";

export interface TimelineItem {
  title: ReactNode;
  /** ISO 时间（缺省为纯步骤节点） */
  at?: string | number | Date;
  state: TimelineItemState;
  /** 附加说明行 */
  detail?: ReactNode;
  /** 右侧动作（如重试） */
  actions?: ReactNode;
}

const dotClass: Record<TimelineItemState, string> = {
  done: "border-status-success/50 bg-status-success-bg text-status-success",
  running: "border-primary/50 bg-primary/10 text-primary",
  waiting: "text-muted-foreground border-border bg-muted",
  failed: "border-status-danger/50 bg-status-danger-bg text-status-danger",
};

const lineClass: Record<TimelineItemState, string> = {
  done: "bg-status-success/40",
  running: "bg-primary/40",
  waiting: "bg-border",
  failed: "bg-status-danger/40",
};

/** 垂直时间线：节点三态（done ✓ / running 转圈 / waiting 空点；failed 复用 danger 语义）。 */
export function Timeline({ items, className }: { items: TimelineItem[]; className?: string }) {
  const { prefs } = useDateTimePrefs();
  return (
    <ol className={cn("flex flex-col", className)}>
      {items.map((item, index) => {
        const isLast = index === items.length - 1;
        return (
          <li key={index} className="grid grid-cols-[24px_1fr] gap-3">
            {/* 节点 + 连线 */}
            <div className="flex flex-col items-center">
              <span
                aria-hidden="true"
                className={cn(
                  "z-10 flex size-6 shrink-0 items-center justify-center rounded-full border",
                  dotClass[item.state],
                )}
              >
                {item.state === "done" ? (
                  <Check className="size-3.5" />
                ) : item.state === "running" ? (
                  <Loader2 className="size-3 animate-spin" />
                ) : null}
              </span>
              {!isLast ? (
                <span aria-hidden="true" className={cn("w-px flex-1", lineClass[item.state])} />
              ) : null}
            </div>
            {/* 内容 */}
            <div className={cn("flex flex-col gap-1 pb-6", isLast && "pb-0")}>
              <div className="flex flex-wrap items-baseline justify-between gap-x-3">
                <span
                  className={cn(
                    "text-sm",
                    item.state === "waiting" ? "text-muted-foreground" : "font-medium",
                  )}
                >
                  {item.title}
                </span>
                {item.at !== undefined ? (
                  <time
                    className="text-muted-foreground text-xs"
                    dateTime={new Date(item.at).toISOString()}
                    title={formatAbsolute(item.at, prefs)}
                  >
                    {formatRelative(item.at)}
                  </time>
                ) : null}
              </div>
              {item.detail ? (
                <div className="text-muted-foreground text-sm">{item.detail}</div>
              ) : null}
              {item.actions ? (
                <div className="mt-1 flex items-center gap-2">{item.actions}</div>
              ) : null}
            </div>
          </li>
        );
      })}
    </ol>
  );
}

import type { CanFn } from "@patterns-ui/core/auth";
import { filterByCanFn, useCan } from "@patterns-ui/core/auth";
